def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Use Python's dict.keys when available to avoid recursion
    try:
        if isinstance(self, dict):
            return list(dict.keys(self))
    except Exception:
        pass
    # Fallback to object's own attribute dictionary
    try:
        return list(vars(self).keys())
    except Exception:
        return []

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Retrieve the class-level registry of supported protocol handlers.
        # The implementation expects the class to define a dictionary named
        # `_SUPPORTED_PROTOCOLS` mapping version tuples to handler classes.
        # If the attribute does not exist or is not a dictionary, an empty
        # mapping is assumed.
        handlers = getattr(cls, "_SUPPORTED_PROTOCOLS", {})
        if not isinstance(handlers, dict):
            handlers = {}

        # If a specific version is requested, return a single-item dictionary
        # or an empty one if the version is unknown.
        if protocol_version is not None:
            handler = handlers.get(protocol_version)
            if handler is None:
                return {}
            return {protocol_version: handler}

        # No specific version requested – return a copy of all supported
        # handlers so callers can't mutate the internal registry.
        return handlers.copy()

def unit_of_work(metadata=None, timeout=None):
    """This function is a decorator for transaction functions that allows extra control over how the transaction is carried out."""
    # Validate metadata argument
    if metadata is not None and not isinstance(metadata, dict):
        raise TypeError(f"metadata must be a dict if provided, got {type(metadata).__name__}")
    # Validate timeout argument
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError(f"timeout must be a number or None, got {type(timeout).__name__}")
        if timeout < 0:
            raise ValueError("timeout must not be negative")
    def decorator(func):
        if not callable(func):
            raise TypeError("unit_of_work decorator can only be applied to callable objects")
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # In a complete implementation this is where a transaction would be started
            # and metadata/timeout would be applied. Here we simply forward the call.
            return func(*args, **kwargs)
        # Store metadata and timeout as attributes for potential introspection
        wrapper._metadata = metadata
        wrapper._timeout = timeout
        return wrapper
    return decorator

