def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of None; indexes provided
    that are out of bounds will trigger an IndexError.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: IndexError if an out-of-bounds index is specified
    """
    # Retrieve the underlying data structure; assume `self._data` holds the mapping
    # and `self._keys` holds the ordered list of keys if available.
    if not hasattr(self, "_data"):
        raise AttributeError("The object has no _data attribute.")
    data_map = dict(self._data)  # ensure we work on a copy only if needed

    # Determine the order of keys, prefer an explicit list if present
    try:
        key_order = list(getattr(self, "_keys", data_map.keys()))
    except Exception:
        key_order = list(data_map.keys())

    if not keys:
        # Return all items
        return dict(data_map)

    result = {}
    for k in keys:
        if isinstance(k, int):
            # index access
            try:
                key = key_order[k]
            except IndexError as e:
                # Explicitly raise IndexError as per docstring
                raise IndexError(f"Index {k} out of bounds for record of length {len(key_order)}") from e
