            raise TypeError("db must be a string if provided")

        if imp_user is not None and not isinstance(imp_user, str):
            raise TypeError("imp_user must be a string if provided")

        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict mapping type to function")

        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict mapping type to function")

