            params["tx_timeout"] = int(timeout * 1000)
        if db is not None:
            params["database"] = db
        if imp_user is not None:
            params["impersonatedUser"] = imp_user

        # ------------------------------------------------------------------
        # Append message to the output queue
        # ------------------------------------------------------------------
