def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    try:
        field_list = list(fields)
    except TypeError:
        raise TypeError("fields must be an iterable")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Build initializer
    def __init__(self, *args, **kwargs):
        if args and len(args) != len(field_list):
            raise TypeError(
                f"{name} init takes {len(field_list)} positional arguments but {len(args)} were given"
            )
        for i, field in enumerate(field_list):
            if i < len(args):
                value = args[i]
            else:
                value = kwargs.get(field)
            setattr(self, field, value)
        # Store SRID map for reference
        self.srid_map = srid_map

    # Representation for debugging
    def __repr__(self):
        pieces = [f"{fld}={getattr(self, fld, None)!r}" for fld in field_list]
        return f"<{name}({', '.join(pieces)})>"

    # Assemble class dictionary
    cls_dict = {"__init__": __init__, "__repr__": __repr__, "_srid_map": srid_map}

    # Determine base class: use existing Point if available, otherwise object
    try:
        Base = Point  # may raise NameError if Point isn't defined
    except NameError:
        Base = object

    # Create and return the new subclass
    return type(name, (Base,), cls_dict)

def deprecated(message):
    warnings = __import__('warnings')
    functools = __import__('functools')

    def decorator(func):
        if not callable(func):
            raise TypeError(f"{func!r} is not callable")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=warnings.DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Converts a version string into a tuple of integers.
    Non-digit separators are ignored and numeric groups are extracted.

    Examples
    --------
    >>> parse_version("1.2.3")
    (1, 2, 3)
    >>> parse_version("v1.02.beta")
    (1, 2)
    >>> parse_version("")
    ()
    >>> parse_version(None)
    ()
    """
    if not isinstance(s, str):
        return ()
    try:
        import re
    except Exception:
        return ()
    parts = re.findall(r'\d+', s)
    if not parts:
        return ()
    try:
        return tuple(int(part) for part in parts)
    except Exception:
        return ()

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key(*args, **kwargs)
            except Exception as exc:
                raise RuntimeError("Key function raised an exception") from exc
            if lock:
                # Try to use the lock as a context manager; fall back to acquire/release.
                try:
                    with lock:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                except Exception:
                    # Fallback if the lock is not a context manager.
                    lock.acquire()
                    try:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                    finally:
                        lock.release()
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is None:
        raise ValueError("maxsize cannot be None")
    if maxsize < 0:
        raise ValueError("maxsize must be non-negative")
    if maxsize == 0:
        # No caching
        def decorator(func):
            return func
        return decorator

    def decorator(func):
        cache = {}
        order = []  # List of keys in usage order, most recent at the end
        def _make_key(args, kwargs):
            key = args
            if kwargs:
                for item in sorted(kwargs.items()):
                    key += item
            if typed:
                for v in kwargs.values():
                    key += (type(v),)
                for a in args:
                    key += (type(a),)
            return key

        def wrapper(*args, **kwargs):
            try:
                key = _make_key(args, kwargs)
            except TypeError:
                # Unhashable arguments, bypass cache
                return func(*args, **kwargs)
            if key in cache:
                # Move key to the end (most recent)
                order.remove(key)
                order.append(key)
                return cache[key]
            # Compute result
            result = func(*args, **kwargs)
            # Add to cache
            cache[key] = result
            order.append(key)
            # Evict if necessary
            if len(cache) > maxsize:
                # Remove the most recently used item
                mru_key = order.pop()
                del cache[mru_key]
            return result

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__wrapped__ = func
        return wrapper
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Check if the container is empty
    try:
        length = len(self)
    except Exception:
        # Fallback to iterator if len is not implemented
        length = None
    if length is not None:
        if length == 0:
            raise KeyError('dictionary is empty')
    else:
        # Attempt to get the first key via iterator
        try:
            key = next(iter(self))
        except StopIteration:
            raise KeyError('dictionary is empty')
    # Retrieve the first key if not already obtained
    try:
        key
    except NameError:
        key = next(iter(self))
    # Get the associated value
    try:
        value = self[key]
    except Exception as exc:
        raise KeyError(f'Key {key!r} not found') from exc
    # Remove the key from the container
    try:
        del self[key]
    except Exception as exc:
        raise KeyError(f'Key {key!r} could not be deleted') from exc
    return key, value

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key] if key in self else default
    except Exception:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """
    Decorator to cache the return value of a class or instance method.
    `cache` should be a mutable mapping such as dict.
    `key` is a callable that receives the instance and the method arguments
    and returns a hashable cache key.
    An optional `lock` can be supplied to make cache access thread‑safe.
    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            # Compute cache key
            try:
                cache_key = key(self, *args, **kwargs)
            except Exception:
                # Fallback key: include function name, args and sorted kwargs
                cache_key = (func.__name__, args, tuple(sorted(kwargs.items())))
            # Choose the cache access strategy
            lock_context = lock
            # If a lock is provided, use it as a context manager
            if lock_context is not None:
                try:
                    # Support objects that provide __enter__/__exit__
                    lock_context.__enter__()
                except AttributeError:
                    # Not a context manager: try to call acquire/release
                    try:
                        lock_context.acquire()
                    except AttributeError:
                        lock_context = None
            try:
                # If lock context established, use the lock
                if lock_context is not None:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(self, *args, **kwargs)
                    cache[cache_key] = result
                    return result
                # No lock: straightforward access
                if cache_key in cache:
                    return cache[cache_key]
                result = func(self, *args, **kwargs)
                cache[cache_key] = result
                return result
            finally:
                if lock_context is not None:
                    try:
                        lock_context.__exit__(None, None, None)
                    except AttributeError:
                        try:
                            lock_context.release()
                        except AttributeError:
                            pass
        return wrapper
    return decorator

@staticmethod
def file_to_textbuffer(file_name, encoding):
    """
    Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
    CAUTION : This will read the whole file IN MEMORY.
    :param file_name: File name.
    :type file_name: str
    :param encoding: Encoding to use.
    :type encoding: str
    :return: A text buffer or None in case of error.
    :rtype str or None
    """
    if not isinstance(file_name, str) or not isinstance(encoding, str):
        return None
    try:
        with open(file_name, 'r', encoding=encoding) as f:
            return f.read()
    except (OSError, UnicodeError):
        return None

@staticmethod
    def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        if not isinstance(file_name, str) or not file_name:
            return False
        try:
            with open(file_name, 'rb'):
                return True
        except (FileNotFoundError, PermissionError, IsADirectoryError, OSError, TypeError):
            return False
        except Exception:
            return False

def _getTargetClass(self):
    """
    Return the implementation in use without the trailing 'Py' or 'Fallback' suffix.
    If the implementation name does not include these suffixes, it is returned unchanged.
    Raises:
        AttributeError: If the instance does not have an 'implementation' attribute.
        TypeError: If the 'implementation' attribute is not a string.
    """
    # Retrieve the implementation attribute
    try:
        impl = getattr(self, 'implementation')
    except AttributeError:
        raise AttributeError(
            "The object does not have an 'implementation' attribute."
        )

    if not isinstance(impl, str):
        raise TypeError(
            f"Expected implementation to be a string, got {type(impl).__name__}"
        )

    # Strip recognized suffixes
    for suffix in ('Py', 'Fallback'):
        if impl.endswith(suffix):
            return impl[: -len(suffix)]
    return impl

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    if classes is None:
        return []

    result = []
    for base in classes:
        # Validate that each base is a class
        if not isinstance(base, type):
            raise TypeError(f"Base {base!r} is not a class")
        # Skip if an earlier base is a subclass of this one
        # (i.e. this base is an ancestor; it is already represented)
        skip = False
        for seen in result:
            try:
                if issubclass(seen, base):
                    skip = True
                    break
            except TypeError:
                # In practice, seen should always be a type, we guard anyway
                continue
        if not skip:
            result.append(base)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface.

    The method introspects the class and optionally the instance to collect
    attributes that represent data (i.e., are not callable or built‑in).  For
    each attribute a human readable description is attempted to be retrieved
    from the following sources in order:

    1. A ``_description`` or ``description`` attribute on the descriptor.
    2. For ``property`` objects, the ``fget`` function docstring.
    3. The ``__doc__`` attribute of the attribute value if one exists.
    4. If no description can be found, an empty string is used.

    Parameters
    ----------
    all : bool, optional
        If ``True``, include inherited members and instance attributes in the
        result set.  If ``False`` (default), only attributes defined directly
        on the class are considered, excluding private members that start
        with an underscore.

    Returns
    -------
    dict[str, str]
        Mapping of attribute names to their descriptions.
    """
    import inspect

    result = {}

    # Determine the set of members to inspect
    if all:
        # Include instance attributes and any inherited class members
        # Exclude callables and built‑in objects
        members = inspect.getmembers(
            self,
            lambda a: not (inspect.isroutine(a) or inspect.isbuiltin(a)),
        )
    else:
        # Only consider attributes defined in this class's dictionary
        members = [
            (k, v)
            for k, v in getattr(self.__class__, "__dict__", {}).items()
            if not (inspect.isroutine(v) or inspect.isbuiltin(v))
        ]

    for name, attr in members:
        # Skip private or special members unless 'all' is True
        if not all and name.startswith("_"):
            continue

        # Skip methods and other callables (double‑check)
        if callable(attr):
            continue

        desc = None

        # 1. Try descriptor specific attributes
        for dname in ("_description", "description"):
            if hasattr(attr, dname):
                try:
                    desc = getattr(attr, dname)
                    break
                except Exception:
                    pass

        # 2. For property descriptors use the fget docstring
        if desc is None and isinstance(attr, property):
            try:
                desc = attr.fget.__doc__
            except Exception:
                desc = None

        # 3. General docstring fallback
        if desc is None and hasattr(attr, "__doc__") and attr.__doc__:
            try:
                desc = attr.__doc__
            except Exception:
                desc = None

        # 4. Representation fallback
        if desc is None:
            try:
                desc = repr(attr)
            except Exception:
                desc = ""

        # Normalize to string
        if not isinstance(desc, str):
            try:
                desc = str(desc)
            except Exception:
                desc = ""

        result[name] = desc

    return result

def names(self, all=False):
        """Return the attribute names defined by the interface."""
        if not isinstance(all, bool):
            raise TypeError("Parameter 'all' must be a boolean value.")
        cls = self.__class__
        bases = cls.__mro__ if all else (cls,)
        name_set = set()
        for base in bases:
            if base is object:  # skip base object
                continue
            # Include attributes stored directly on the class dict
            for name, value in vars(base).items():
                if name.startswith("_"):  # ignore private / dunder names
                    continue
                if callable(value):
                    continue
                name_set.add(name)
            # Include attributes declared via type annotations
            annotations = getattr(base, "__annotations__", {})
            for name in annotations:
                if name.startswith("_"):
                    continue
                name_set.add(name)
        return sorted(name_set)

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import c_optimizations
    except ImportError as exc:
        # If the optional C extension cannot be imported, we return False.
        # The caller may decide whether this is acceptable or raise the error.
        return False
    except Exception as exc:
        # A more serious error (e.g., binary incompatibility) might raise a different exception;
        # re‑raise as ImportError to signal a missing dependency.
        raise ImportError("Could not load C optimizations") from exc
    else:
        return c_optimizations

def reset(self):
        """
        Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset context
        self.context = {}

        # Reinitialize bins
        # If an initial_value attribute exists and is not None use it,
        # otherwise attempt to call a method named make_bins to create bins.
        try:
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # Use a copy if mutable to avoid shared state
                try:
                    from copy import deepcopy
                    self.bins = deepcopy(self.initial_value)
                except Exception:
                    # Fallback: assign directly if deepcopy fails
                    self.bins = self.initial_value
            elif hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If no way to construct bins, raise an informative error
                raise AttributeError(
                    "Histogram cannot be reset: no 'initial_value' or 'make_bins' available."
                )
        except Exception as e:
            # Wrap unexpected errors to provide context
            raise RuntimeError(f"Failed to reset histogram bins: {e}") from e

        # Ensure bins is not None
        if self.bins is None:
            raise RuntimeError("Histogram bins initialization resulted in None.")

def _update_context(self, context):
        """
        Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.
        """
        if context is None or not isinstance(context, dict):
            return

        # Ensure error dictionary exists
        err_ctx = context.setdefault('error', {})

        # Determine coordinate names in order; fallbacks if attributes missing
        coord_names = []
        try:
            if hasattr(self, 'coordinates'):
                coord_names = list(self.coordinates)
            elif hasattr(self, 'field_names'):
                coord_names = list(self.field_names)
            elif hasattr(self, '_fields'):
                # Assume _fields is iterable of objects with attribute 'name'
                coord_names = [f.name for f in self._fields if hasattr(f, 'name')]
        except Exception:
            coord_names = []

        # Map coordinate indices to prefixes
        coord_prefix = {idx: pref for idx, pref in enumerate(['x', 'y', 'z'])}

        # Helper to extract coordinate index from error field name
        def get_coord_index(name):
            # name format: "<coord>_<suffix>" or just "<coord>"
            try:
                key = name.split('_', 1)[0]
                return coord_names.index(key)
            except Exception:
                return None

        # Iterate over error fields defined in this graph
        for attr_name in dir(self):
            if not attr_name.startswith('error_'):
                continue
            # Resolve the error object
            try:
                err_obj = getattr(self, attr_name)
            except Exception:
                continue

            # Obtain index attribute if present
            index = getattr(err_obj, 'index', None)
            if index is None:
                # Some error objects might store index in a property named 'indices' or similar
                index = getattr(err_obj, 'indices', None)
                if isinstance(index, (list, tuple)) and index:
                    index = index[0]
            if index is None:
                continue

            # Parse the rest of the name after 'error_'
            rest_name = attr_name[len('error_') :]
            # Determine coordinate prefix
            coord_idx = get_coord_index(rest_name)
            if coord_idx is not None:
                prefix = coord_prefix.get(coord_idx, 'x')
            else:
                # If nothing matches, try simple order or default to x
                # Count previous errors to assign sequential prefixes
                prefix = 'x'
            # Build the suberror key
            rest_parts = rest_name.split('_', 1)
            if len(rest_parts) == 2:
                sub_key = f"{prefix}_{rest_parts[1]}"
            else:
                sub_key = f"{prefix}"
            # Append to context
            err_ctx[sub_key] = {'index': index}
        # No explicit return; context is modified in place

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate bin sequence
    try:
        n_bins = len(bins)
    except Exception as exc:
        raise TypeError("bins must be a sequence of numeric values") from exc

    # Validate edges sequence and convert to list for indexing
    try:
        edges_list = list(edges)
    except Exception as exc:
        raise TypeError("edges must be a sequence of numeric values") from exc

    # Ensure the number of edges is one more than the number of bins
    if len(edges_list) != n_bins + 1:
        raise ValueError(
            f"Number of edges ({len(edges_list)}) must equal number of bins ({n_bins}) + 1"
        )

    # Compute the integral as the sum over bin heights times bin widths
    total = 0.0
    for bin_height, edge_left, edge_right in zip(bins, edges_list[:-1], edges_list[1:]):
        try:
            bin_height_val = float(bin_height)
            width = float(edge_right - edge_left)
            total += bin_height_val * width
        except Exception as exc:
            raise TypeError(
                f"Non numeric bin height or edge encountered: {bin_height!r}, {edge_left!r}, {edge_right!r}"
            ) from exc

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct instance of FillRequest
    if isinstance(seq, FillRequest):
        return True

    # Exclude Source sequences explicitly
    if isinstance(seq, Source):
        return False

    # Non-iterable or string/bytes are not considered valid sequences
    if not hasattr(seq, "__iter__") or isinstance(seq, (str, bytes)):
        return False

    # Check for presence of a FillRequest element
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except Exception:
        # If iteration fails (e.g., closed generator), treat as invalid
        return False

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        fill_attr = getattr(obj, "fill", None)
        request_attr = getattr(obj, "request", None)
        return callable(fill_attr) and callable(request_attr)
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run'))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return callable(getattr(obj, "fill", None)) and callable(getattr(obj, "compute", None))
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("difference() arguments must be dictionaries")
    # level == 0 means no processing
    if level == 0:
        return {}
    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Include as-is (reference to the original value)
            result[key] = val1
        else:
            val2 = d2[key]
            # If values are equal, skip
            if val1 == val2:
                continue
            # If both values are dicts and we are allowed to recurse, do so
            if (
                isinstance(val1, dict)
                and isinstance(val2, dict)
                and (level == -1 or level > 1)
            ):
                sub_diff = difference(val1, val2, level - 1 if level > 0 else -1)
                if sub_diff:
                    result[key] = sub_diff
            else:
                # Different values (or not both dicts); copy as-are
                result[key] = val1
    return result

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Normalize coordinates to a tuple
        try:
            is_iterable = hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes))
        except Exception:
            is_iterable = False
        if not is_iterable:
            coord = (coord,)
        else:
            coord = tuple(coord)

        # Validate dimensions
        if not hasattr(self, "_edges"):
            raise AttributeError("Histogram missing '_edges' attribute.")
        if not hasattr(self, "_data"):
            raise AttributeError("Histogram missing '_data' attribute.")

        ndim = len(self._edges)
        if len(coord) != ndim:
            raise ValueError(f"Coordinate length {len(coord)} does not match histogram dimensions {ndim}.")

        # Validate weight
        try:
            weight_val = float(weight)
        except Exception:
            raise TypeError(f"Weight '{weight}' is not a numeric value.")

        # Find bin indices for each coordinate
        bin_indices = []
        try:
            from bisect import bisect_right
        except Exception as e:
            raise ImportError("Failed to import bisect module.") from e

        for dim, (value, edges) in enumerate(zip(coord, self._edges)):
            # Ensure edges is a sequence
            try:
                edges_seq = list(edges)
            except Exception:
                raise TypeError(f"Edges for dimension {dim} must be a sequence.")
            if not edges_seq:
                raise ValueError(f"Edge list for dimension {dim} is empty.")

            # Place value in bin: edges[i] <= value < edges[i+1]
            pos = bisect_right(edges_seq, value) - 1
            # Check bounds
            if pos < 0 or pos >= self._data.shape[dim]:
                # Outside histogram bounds
                return
            bin_indices.append(pos)

        # Increment the histogram bin
        try:
            self._data[tuple(bin_indices)] += weight_val
        except Exception as e:
            raise RuntimeError(f"Failed to increment histogram bin at indices {bin_indices}.") from e

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Basic validation of input
    if not isinstance(labels, dict):
        raise TypeError("labels must be a dict")

    # Regular expressions for keys and values
    key_pattern = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_.]*$')
    value_pattern = re.compile(r'^[^,]{1,255}$')  # Simplified placeholder pattern

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not key_pattern.fullmatch(key):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Validate value
        if isinstance(value, list):
            # If value is a list, treat each element separately
            for element in value:
                if not isinstance(element, (str, bytes)):
                    errors.append({str(element): 'expected string or bytes-like object'})
                else:
                    if not value_pattern.fullmatch(element):
                        errors.append({element: f"Label value '{element}' does not match the regex [...]"})
        else:
            # Non-list value
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not value_pattern.fullmatch(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        # Assuming ValidationError is defined elsewhere with a `messages` attribute
        raise ValidationError(errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    try:
        ValidationError
    except NameError:
        class ValidationError(Exception):
            """Fallback ValidationError if not defined elsewhere."""
            pass

    if not isinstance(value, str):
        raise ValidationError("Value must be a string")

    # Simple alphanumeric validation (acts as a stand‑in for a real regex)
    if not value.isalnum():
        raise ValidationError("Value must contain only alphanumeric characters")

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Defensive checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(response, list):
        # Nothing to do if the response is not a list
        return
    # If no schema is provided, simply copy response elements
    if observer_schema is None:
        for i, item in enumerate(response):
            if i < len(last_applied_manifest):
                last_applied_manifest[i] = item
            else:
                last_applied_manifest.append(item)
        return
    # Iterate over response items
    for idx, resp_item in enumerate(response):
        # Ensure there is a corresponding element in the manifest
        if idx < len(last_applied_manifest):
            current = last_applied_manifest[idx]
        else:
            # Create a placeholder for a new element
            current = {}
            last_applied_manifest.append(current)
        # Handle dict-like objects
        if isinstance(resp_item, dict):
            # If current is not a dict, replace it
            if not isinstance(current, dict):
                current = {}
                last_applied_manifest[idx] = current
            # Recursively populate the dict
            try:
                update_last_applied_manifest_dict_from_resp(
                    current, observer_schema, resp_item
                )
            except Exception as exc:
                # If the nested update fails, raise with context
                raise RuntimeError(
                    f"Failed to update dict at index {idx} in list: {exc}"
                ) from exc
        # Handle nested lists
        elif isinstance(resp_item, list):
            # If current is not a list, replace it
            if not isinstance(current, list):
                current = []
                last_applied_manifest[idx] = current
            # Determine a suitable sub‑schema for the nested list items
            sub_schema = None
            if isinstance(observer_schema, list) and len(observer_schema) == 1:
                # Assume the list schema is a single‑item list describing the element
                sub_schema = observer_schema[0]
            # Recurse into the nested list
            try:
                update_last_applied_manifest_list_from_resp(
                    current, sub_schema, resp_item
                )
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to update nested list at index {idx} in list: {exc}"
                ) from exc
        # Handle primitive types
        else:
            last_applied_manifest[idx] = resp_item
    # Any remaining items in last_applied_manifest beyond the response length are left untouched
    return

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
        TypeError: If the provided arguments are not dictionaries

    This function goes through all observed fields in ``observer_schema``, and
    initializes their value in ``last_applied_manifest`` if they are not yet
    present.  It handles nested dictionaries by recursing and delegates list
    handling to :func:`update_last_applied_manifest_list_from_resp`.
    """
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, dict):
        raise TypeError(
            f"observer_schema must be a dict, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response).__name__}"
        )

    for key, schema_value in observer_schema.items():
        # Ensure the key exists in the response
        if key not in response:
            raise KeyError(
                f"Observed field '{key}' missing from Kubernetes response"
            )
        resp_val = response[key]

        # Handle nested dictionaries
        if isinstance(schema_value, dict) and isinstance(resp_val, dict):
            # Ensure a dict exists in the target
            target_dict = last_applied_manifest.get(key)
            if target_dict is None:
                target_dict = {}
                last_applied_manifest[key] = target_dict
            elif not isinstance(target_dict, dict):
                # If the existing value is not a dict, replace it
                target_dict = {}
                last_applied_manifest[key] = target_dict
            # Recurse into the nested dict
            update_last_applied_manifest_dict_from_resp(
                target_dict, schema_value, resp_val
            )
        else:
            # Primitive scalar or list handling
            if isinstance(resp_val, list):
                # Delegate list handling
                if key not in last_applied_manifest or not isinstance(
                    last_applied_manifest[key], list
                ):
                    last_applied_manifest[key] = []
                # The list handling function is assumed to be available in the same module
                # It may raise its own exceptions as needed
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema_value, resp_val
                )
            else:
                # Only set if not already present
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = resp_val
    # The function mutates `last_applied_manifest` in place and returns None
    return None

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        raise ValueError("app cannot be None")

    # Extract the manifest and existing observer schemas safely
    try:
        manifest = getattr(app.spec, "manifest", [])
        if manifest is None:
            manifest = []
        # ``observer_schema`` is expected to be a dict that maps resource names
        # to their observer schema definitions.
        observer_schemas = getattr(app.spec, "observer_schema", {})
        if observer_schemas is None:
            observer_schemas = {}
    except AttributeError as exc:
        raise ValueError("app.spec does not expose expected attributes") from exc

    # Ensure we work with a mutable dict
    if not isinstance(observer_schemas, dict):
        raise TypeError("app.spec.observer_schema must be a dict")

    # Iterate over each resource in the manifest
    for idx, resource in enumerate(manifest):
        # Guard against non-dict entries in the manifest
        if not isinstance(resource, dict):
            continue

        metadata = resource.get("metadata", {})
        if not isinstance(metadata, dict):
            continue

        name = metadata.get("name")
        kind = resource.get("kind")

        # Skip resources without a name or kind
        if not name or not kind:
            continue

        # If a custom observer schema is already present, skip generation
        if name in observer_schemas:
            continue

        # Create a simple default observer schema.  This example uses the
        # resource kind and name; adjust as needed for your specific domain.
        default_schema = {
            "kind": kind,
            "apiVersion": resource.get("apiVersion", ""),
            "metadata": {"name": name},
        }

        # Store the default schema
        try:
            observer_schemas[name] = default_schema
        except TypeError:
            # If observer_schemas was an immutable mapping, recreate it
            observer_schemas = dict(observer_schemas, **{name: default_schema})

    # Assign the updated schemas back to the application spec
    try:
        app.spec.observer_schema = observer_schemas
    except Exception as exc:
        raise RuntimeError("Failed to set observer_schema on app.spec") from exc

    return app

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		"""
		Convert a SQL query that uses in‑style parameters into a form that
		can be executed with out‑style parameters.
		For a mapping of ``{name: value}`` the named parameters
		(``:name``) in *sql* are replaced by the question mark placeholder
		(`?`) and the values are returned in a list in the order in which
		the placeholders appear.  For an ordinal sequence the function
		makes sure that the number of ``?`` placeholders matches the
		length of the sequence and simply returns the original SQL
		unchanged together with a copy of the sequence.
		"""
		if isinstance(params, dict):
			# Named parameters – replace :name with ?
			if isinstance(sql, bytes):
				try:
					s = sql.decode("utf-8")
				except Exception:
					s = sql.decode("utf-8", errors="ignore")
			else:
				s = sql
			values: List[Any] = []
			new_parts: List[str] = []
			idx = 0
			length = len(s)
			while idx < length:
				ch = s[idx]
				if ch == ":":
					# attempt to parse a name
					j = idx + 1
					while j < length and (s[j].isalnum() or s[j] == "_"):
						j += 1
					if j > idx + 1:  # found a name
						name = s[idx + 1 : j]
						if name not in params:
							raise ValueError(f"Missing parameter: {name}")
						values.append(params[name])
						new_parts.append("?")
						idx = j
						continue
				new_parts.append(ch)
				idx += 1
			new_sql = "".join(new_parts)
			if isinstance(sql, bytes):
				new_sql = new_sql.encode("utf-8")
			return new_sql, values

		# Ordinal parameters – only support question‑mark style
		if isinstance(params, Sequence) and not isinstance(
			params, (str, bytes)
		):
			if isinstance(sql, bytes):
				try:
					s = sql.decode("utf-8")
				except Exception:
					s = sql.decode("utf-8", errors="ignore")
			else:
				s = sql
			placeholder_count = s.count("?")
			if placeholder_count != len(params):
				raise ValueError(
					"Number of parameters does not match number of placeholders"
				)
			# Ensure returning a list for consistency
			return sql, list(params)

		raise TypeError(
			"params must be a mapping or a sequence, not " + str(type(params))
		)

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve path-like objects
        os = __import__('os')
        p = os.fspath(path)
        # Ensure the path exists and is a directory
        if not os.path.isdir(p):
            return False
        # A minimal check: a valid OCFL root should contain an 'objects' directory
        try:
            entries = os.listdir(p)
        except Exception:
            return False
        if 'objects' in entries:
            return True
        # Fallback: look for a manifest file typical of an OCFL repo
        for entry in entries:
            if entry.lower().startswith('manifest') and entry.lower().endswith('.json'):
                return True
        # If none of the checks pass, consider it invalid
        return False
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Validate the prefix argument
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")

    # Attempt to retrieve the validator status from known attributes.
    # Use a cascading approach with sensible fallbacks.
    status = None
    for attr in ('status', 'state', 'status_text', 'message', 'error'):
        if hasattr(self, attr):
            status = getattr(self, attr, None)
            if status is not None:
                break

    # If no explicit status was found, use the string representation
    # of the object as a last resort.
    if status is None:
        status = str(self)

    # Ensure status is a string; if it is a collection, join its elements.
    if isinstance(status, (list, tuple, set)):
        status = ', '.join(map(str, status))
    else:
        status = str(status)

    return f"{prefix}{status}"

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        if not isinstance(manifest_files, (list, tuple)):
            raise TypeError(f"manifest_files must be a list or tuple, got {type(manifest_files).__name__}")
        # Ensure digests_used is a set
        try:
            digests_used_set = set(digests_used)
        except Exception as e:
            raise TypeError(f"digests_used must be an iterable of digest strings: {e}")

        required_digests = set()
        for path in manifest_files:
            if not isinstance(path, str):
                raise TypeError(f"Each entry in manifest_files must be a string path, got {type(path).__name__}")
            try:
                with open(path, "r") as f:
                    for line in f:
                        digest = line.strip()
                        if digest:
                            required_digests.add(digest)
            except FileNotFoundError:
                raise FileNotFoundError(f"Manifest file not found: {path}")
            except Exception as e:
                raise IOError(f"Error reading manifest file '{path}': {e}")

        missing_in_use = required_digests - digests_used_set
        unused_in_manifest = digests_used_set - required_digests

        if missing_in_use or unused_in_manifest:
            messages = []
            if missing_in_use:
                messages.append(f"Missing digests in usage: {sorted(missing_in_use)}")
            if unused_in_manifest:
                messages.append(f"Digests used but not present in manifest: {sorted(unused_in_manifest)}")
            raise ValueError("; ".join(messages))

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is not None
        if prior is None:
            raise ValueError("Provided prior object is None, which is not a valid prior version.")

        # Ensure prior is an instance of the same type as self
        if not isinstance(prior, type(self)):
            raise TypeError(f"Provided prior object must be of type {type(self).__name__}, "
                            f"got {type(prior).__name__} instead.")

        # Ensure prior is not the same instance as self
        if prior is self:
            raise ValueError("Provided prior object is the same as the current inventory; "
                             "a prior version must be distinct.")

        # Helper to safely get attributes
        def _get_attr(obj, attr, default=None):
            return getattr(obj, attr, default)

        # Check unique identifier consistency (if present)
        self_id = _get_attr(self, 'id', None)
        prior_id = _get_attr(prior, 'id', None)
        if (self_id is not None or prior_id is not None) and self_id != prior_id:
            raise ValueError(f"Identifier mismatch: current inventory id={self_id} differs from prior id={prior_id}.")

        self_uuid = _get_attr(self, 'uuid', None)
        prior_uuid = _get_attr(prior, 'uuid', None)
        if (self_uuid is not None or prior_uuid is not None) and self_uuid != prior_uuid:
            raise ValueError(f"UUID mismatch: current uuid={self_uuid} differs from prior uuid={prior_uuid}.")

        # Check version ordering (if present)
        self_version = _get_attr(self, 'version', None)
        prior_version = _get_attr(prior, 'version', None)
        if self_version is not None and prior_version is not None:
            try:
                if not prior_version < self_version:
                    raise ValueError(f"Invalid version ordering: prior version={prior_version} is not less than current version={self_version}.")
            except TypeError:
                # If versions are not comparable, skip this check
                pass

        # Check timestamp ordering (if present)
        self_ts = _get_attr(self, 'timestamp', None)
        prior_ts = _get_attr(prior, 'timestamp', None)
        if self_ts is not None and prior_ts is not None:
            try:
                # Assume timestamps support comparison operators
                if not prior_ts < self_ts:
                    raise ValueError(f"Timestamp of prior ({prior_ts}) is not earlier than current ({self_ts}).")
            except TypeError:
                # If timestamps are not comparable, skip this check
                pass

        # All checks passed
        return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Result mapping
    mapping = {}

    # Fetch version-specific data; if not present, return empty dict
    version_data = inventory.get(version)
    if version_data is None:
        return mapping

    def _walk(node, current_key):
        """
        Recursively traverse the node to build mapping from logical path to set of content files.
        """
        # If node is a dictionary, dive into its key-value pairs
        if isinstance(node, dict):
            for key, value in node.items():
                # Build the full logical path by joining with '/'
                full_key = f"{current_key}/{key}".lstrip("/")
                _walk(value, full_key)
        # If node is a list, set, or tuple, treat it as the set of content files
        elif isinstance(node, (list, set, tuple)):
            mapping[current_key] = set(node)
        else:
            # Primitive value (e.g., a string path); wrap into a set
            mapping[current_key] = {node}

    _walk(version_data, "")

    return mapping

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Ensure the fixity block is a dictionary or a list of dictionaries, contains
    the required 'checksum' and 'checksum_method' keys for each entry, and
    that any referenced file names are present in the supplied ``manifest_files``.

    Parameters
    ----------
    fixity : dict or list
        The provided fixity block from the inventory.
    manifest_files : Iterable[str]
        A collection of file names that are expected to be referenced by the
        fixity block.

    Raises
    ------
    ValueError
        If the fixity structure is invalid or if a referenced file is not in
        ``manifest_files``.
    """
    import collections

    # Ensure we have an iterable of entries
    if isinstance(fixity, collections.abc.Mapping):
        entries = [fixity]
    elif isinstance(fixity, collections.abc.Sequence) and not isinstance(fixity, (str, bytes)):
        entries = list(fixity)
    else:
        raise ValueError("Fixity block must be a dict or a list of dicts")

    # Normalize manifest_files to a set for fast lookup
    if not isinstance(manifest_files, collections.abc.Hashable):
        manifest_set = set(manifest_files)
    else:
        # If a single string or hashable is given, treat as a single entry
        manifest_set = set([manifest_files])

    # Keys that might contain file references
    FILE_KEYS = {"file", "filepath", "path", "filename", "file_name"}

    for entry_index, entry in enumerate(entries):
        if not isinstance(entry, collections.abc.Mapping):
            raise ValueError(f"Fixity entry {entry_index} is not a dictionary")

        # Validate required fields
        if "checksum" not in entry:
            raise ValueError(f"Fixity entry {entry_index} missing required 'checksum'")
        if "checksum_method" not in entry:
            raise ValueError(f"Fixity entry {entry_index} missing required 'checksum_method'")

        # Detect referenced file(s)
        referenced_files = []

        # Look for explicit file key
        for key in FILE_KEYS:
            if key in entry:
                referenced_files.append(entry[key])

        # If no explicit key, treat top‑level keys that map to dicts as file references
        if not referenced_files:
            for key, val in entry.items():
                if isinstance(val, collections.abc.Mapping):
                    referenced_files.append(key)

        # Ensure all referenced files are in the manifest
        for ref_file in referenced_files:
            if ref_file not in manifest_set:
                raise ValueError(
                    f"Fixity entry {entry_index} references unknown file '{ref_file}' "
                    f"not present in the manifest"
                )
    # If we get here, the fixity block is considered valid
    return None

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Ensure the provided path is handled uniformly
    try:
        # Resolve to an absolute path for consistent behavior
        abs_path = os.path.abspath(path)
    except Exception as e:
        raise ValueError(f"Invalid path '{path}': {e}") from e

    # Check if the path exists
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Path does not exist: {abs_path}")

    # Check if the path is a directory
    if not os.path.isdir(abs_path):
        raise NotADirectoryError(f"Path is not a directory: {abs_path}")

    try:
        entries = os.listdir(abs_path)
    except OSError as e:
        raise OSError(f"Could not list directory contents for {abs_path}: {e}") from e

    files = []
    for entry in entries:
        full_entry = os.path.join(abs_path, entry)
        try:
            if os.path.isfile(full_entry):
                files.append(entry)
        except OSError:
            # Skip entries we cannot stat
            continue

    return sorted(files)

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename.

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source directory (unused but kept for signature consistency).
    xmls : list of str
        List of XML filenames (full paths or basenames).
    files : list of str
        List of files in the folder or zipfile (full paths or basenames).

    Returns
    -------
    dict
        key: name of the XML file (basename with extension)
        value: list of file paths belonging to that XML group
    """
    # Helper to split path and extension without importing os
    def _split_base_ext(name):
        # Extract basename
        name = name.split('/')[-1].split('\\')[-1]
        idx = name.rfind('.')
        if idx == -1:
            return name, ''
        return name[:idx], name[idx + 1 :]

    # Validate inputs
    if not isinstance(xmls, (list, tuple)):
        return {}
    if not isinstance(files, (list, tuple)):
        return {}
    try:
        base_to_xmlkey = {}
        result = {}
        # Build mapping from base to XML key (basename with extension)
        for xml in xmls:
            if not isinstance(xml, str):
                continue
            xml_name = _split_base_ext(xml)[0] + '.' + _split_base_ext(xml)[1] if _split_base_ext(xml)[1] else _split_base_ext(xml)[0]
            base, _ = _split_base_ext(xml_name)
            base_to_xmlkey[base] = xml_name
            result[xml_name] = []

        # Group files
        for file_path in files:
            if not isinstance(file_path, str):
                continue
            file_name = _split_base_ext(file_path)[0] + '.' + _split_base_ext(file_path)[1] if _split_base_ext(file_path)[1] else _split_base_ext(file_path)[0]
            file_base, _ = _split_base_ext(file_name)
            if file_base in base_to_xmlkey:
                xml_key = base_to_xmlkey[file_base]
                result[xml_key].append(file_path)

        return result
    except Exception:
        # On any unexpected error, return empty dict
        return {}

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    if not isinstance(lang, str) or not lang.strip():
        raise ValueError("Language code must be a non-empty string")
    if not isinstance(file_path, str) or not file_path.strip():
        raise ValueError("File path must be a non-empty string")

    # Verify the file exists by attempting to open it in binary mode
    try:
        with open(file_path, 'rb'):
            pass
    except Exception as e:
        raise FileNotFoundError(f"Unable to access the file '{file_path}': {e}")

    # Initialize or retrieve existing renditions mapping
    if not hasattr(self, 'renditions') or not isinstance(self.renditions, dict):
        self.renditions = {}

    # Store the new rendition path keyed by the language code
    self.renditions[lang] = file_path

    # Optionally deduce the original file name if not already present
    if "original" not in self.renditions:
        # Attempt to infer the original by stripping the language suffix
        # e.g., from "artigo02-en.pdf" -> "artigo02.pdf"
        # We look for a hyphen before the language code at the end of the file stem
        # Extract base name without directories
        base = file_path.rsplit('/', 1)[-1]
        if '\\' in base:
            base = base.rsplit('\\', 1)[-1]
        # Split into name and extension
        if '.' in base:
            name, ext = base.rsplit('.', 1)
            parts = name.rsplit('-', 1)
            if len(parts) == 2 and parts[1].lower() == lang.lower():
                original_name = parts[0] + '.' + ext
                # Check that the inferred original file exists
                possible_original = original_name
                try:
                    with open(possible_original, 'rb'):
                        pass
                    self.renditions["original"] = possible_original
                except Exception:
                    # If the inferred original doesn't exist, skip setting it
                    pass
    return None

def add_asset(self, basename, file_path):
    """
    "{
        \"artigo02-gf03.tiff\": \"/path/artigo02-gf03.tiff\",
        \"artigo02-gf03.jpg\": \"/path/artigo02-gf03.jpg\",
        \"artigo02-gf03.png\": \"/path/artigo02-gf03.png\",
    }"
    """
    # Validate input types
    if not isinstance(basename, str):
        raise TypeError("basename must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")

    # Trim whitespace and validate non-empty
    basename = basename.strip()
    file_path = file_path.strip()
    if not basename:
        raise ValueError("basename cannot be empty")
    if not file_path:
        raise ValueError("file_path cannot be empty")

    # Normalize the directory prefix (remove any trailing slash/backslash)
    path_prefix = file_path.rstrip("/")  # Handles Unix style paths; if Windows style is expected, extend accordingly

    # Build mapping for supported extensions
    extensions = ("tiff", "jpg", "png")
    asset_map = {}
    for ext in extensions:
        filename = f"{basename}.{ext}"
        full_path = f"{path_prefix}/{filename}"
        asset_map[filename] = full_path

    return asset_map

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths.
    Se nenhum caminho gerar resultado, retorna None.
    """
    # Validate inputs
    if node is None:
        return None
    if not pubdate_xpaths:
        return None

    # Allow a single xpath string instead of a list/tuple
    if isinstance(pubdate_xpaths, (str, bytes)):
        pubdate_xpaths = [pubdate_xpaths]
    elif not isinstance(pubdate_xpaths, (list, tuple)):
        # Unsupported type, return None early
        return None

    for xpath in pubdate_xpaths:
        try:
            # Attempt to evaluate the xpath on the node
            result = node.xpath(xpath)
        except Exception:
            # Skip errors such as malformed xpath or evaluation problems
            continue

        # Skip if nothing was found
        if not result:
            continue

        # The xpath result may be a list of elements or strings.
        # Inspect each to find a non-empty string value.
        for elem in result:
            # If the element is a string (text node result)
            if isinstance(elem, str):
                value = elem.strip()
                if value:
                    return value
            # If the element is an Element (xml.etree or lxml element)
            else:
                text = getattr(elem, "text", None)
                if text:
                    value = text.strip()
                    if value:
                        return value

    # No match found
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _format(obj, level=0):
        if id(obj) in visited:
            return f"<{type(obj).__name__} ...>"
        visited.add(id(obj))

        indent_unit = "  " * (level + 1)
        curr_indent = "  " * level

        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                items.append(f"{indent_unit}{repr(k)}: {_format(v, level + 1)}")
            if not items:
                return "{}"
            return "{\n" + "\n".join(items) + f"\n{curr_indent}}"  

        if isinstance(obj, (list, tuple, set)):
            open_char, close_char = {"list": ("[", "]"), "tuple": ("(", ")"), "set": ("{", "}")}.get(type(obj).__name__.lower(), ("[", "]"))
            items = []
            for v in obj:
                items.append(f"{indent_unit}{_format(v, level + 1)}")
            if not items:
                return open_char + close_char
            return f"{open_char}\n" + "\n".join(items) + f"\n{curr_indent}{close_char}"

        # Try to pretty-print custom objects
        if hasattr(obj, "__dict__") or hasattr(obj, "__slots__"):
            cls_name = type(obj).__name__
            body_items = []

            # __dict__ attributes
            if hasattr(obj, "__dict__") and isinstance(obj.__dict__, dict):
                for k, v in vars(obj).items():
                    body_items.append(f"{indent_unit}{k}={_format(v, level + 1)}")

            # __slots__ attributes
            if hasattr(obj, "__slots__"):
                slots = getattr(obj, "__slots__")
                if isinstance(slots, str):
                    slots = [slots]
                for sl in slots:
                    try:
                        val = getattr(obj, sl)
                        body_items.append(f"{indent_unit}{sl}={_format(val, level + 1)}")
                    except AttributeError:
                        continue

            if not body_items:
                body = "{}"
            else:
                body = "{\n" + "\n".join(body_items) + f"\n{curr_indent}}}"

            if debug:
                header = f"{cls_name}("
                footer = ")"
                return f"{header}{body}{footer}"
            else:
                return body

        # Fallback to repr
        return repr(obj)

    # The original `indent` argument is preserved for backward compatibility but not used in this simple implementation.
    return _format(self)

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
        etcd_host (str): the host for the database.
        etcd_port (int): the port for the database.

    Returns:
        dict: the created configuration.

    """
    # Validate input types
    if not isinstance(user, str):
        raise TypeError(f"'user' must be a string, got {type(user).__name__}")
    if not isinstance(etcd_host, str):
        raise TypeError(f"'etcd_host' must be a string, got {type(etcd_host).__name__}")
    if not isinstance(etcd_port, int):
        raise TypeError(f"'etcd_port' must be an integer, got {type(etcd_port).__name__}")

    # Validate port range
    if not (0 < etcd_port <= 65535):
        raise ValueError(f"'etcd_port' must be in the range 1-65535, got {etcd_port}")

    # Build configuration dictionary
    config = {
        "auth": {
            "type": "static",
            "user": user
        },
        "etcd": {
            "host": etcd_host,
            "port": etcd_port
        }
    }
    return config

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed,
    to unicode strings
    """
    import sys
    # If running under Python 2, wrap the function so that Unicode return values
    # are encoded to utf-8 bytes. On Python 3 no conversion is needed.
    if sys.version_info[0] < 3:
        def _wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            # In Python 2, unicode is the unicode type. Convert it to bytes.
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except Exception as exc:
                    raise ValueError("Failed to encode tzname() return value: %r" % exc) from exc
            # Return any other type unchanged (e.g., bytes, None, int).
            return result
        return _wrapper
    else:
        # In Python 3, the tzname() function already returns unicode strings.
        return namefunc

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : dict or sequence
        The version components. If a mapping, supported keys are
        ``major``, ``minor``, ``patch``, ``prerelease`` and ``build``.
        If a sequence, it is interpreted as
        (major, minor, patch, prerelease, build) in that order.
    style : str, optional
        The rendering style.

        * ``"semver"`` (default) – full semantic‑version string
          (``major.minor.patch[-prerelease][+build]``).
        * ``"numeric"`` – only ``major.minor.patch``.
        * ``"plain"`` – components joined by a dot, skipping any
          missing parts.

    Returns
    -------
    str
        The rendered version string. Missing components are omitted.
        Empty input yields an empty string.

    Raises
    ------
    TypeError
        If *pieces* is not a mapping or sequence.
    ValueError
        If any component cannot be coerced to a string or integer for
        numeric parts.
    """
    # Helper to convert numeric part
    def _to_int(value, name):
        if value is None:
            return None
        try:
            # Accept ints, strs that are digits, or floats (truncated)
            if isinstance(value, int):
                return value
            if isinstance(value, float):
                return int(value)
            if isinstance(value, str):
                if value.isdigit():
                    return int(value)
                else:
                    raise ValueError
            # Unsupported type
            raise ValueError
        except Exception:
            raise ValueError(f"Invalid {name} component: {value!r}") from None

    # Helper to coerce string component
    def _to_str(value, name):
        if value is None:
            return None
        if isinstance(value, (str, int, float)):
            return str(value)
        raise ValueError(f"Invalid {name} component type: {type(value).__name__}")

    # Parse pieces into recognised parts
    major = minor = patch = prerelease = build = None
    try:
        if isinstance(pieces, dict):
            major = _to_int(pieces.get("major"), "major")
            minor = _to_int(pieces.get("minor"), "minor")
            patch = _to_int(pieces.get("patch"), "patch")
            prerelease = _to_str(pieces.get("prerelease"), "prerelease")
            build = _to_str(pieces.get("build"), "build")
        else:
            # Sequence: interpret in order; ignore extra items
            it = iter(pieces)
            major = _to_int(next(it, None), "major")
            minor = _to_int(next(it, None), "minor")
            patch = _to_int(next(it, None), "patch")
            prerelease = _to_str(next(it, None), "prerelease")
            build = _to_str(next(it, None), "build")
    except TypeError:
        raise TypeError("pieces must be a mapping or sequence of components") from None

    # Build the string according to style
    if style is None or style == "" or style.lower() == "semver":
        # Semantic version string
        if major is None:
            return ""  # No version provided
        parts = [str(major)]
        if minor is not None:
            parts.append(str(minor))
        else:
            parts.append("0")
        if patch is not None:
            parts.append(str(patch))
        else:
            parts.append("0")
        base = ".".join(parts)
        if prerelease:
            base = f"{base}-{prerelease}"
        if build:
            base = f"{base}+{build}"
        return base

    if style.lower() == "numeric":
        if major is None:
            return ""
        parts = [str(major)]
        if minor is not None:
            parts.append(str(minor))
        else:
            parts.append("0")
        if patch is not None:
            parts.append(str(patch))
        else:
            parts.append("0")
        return ".".join(parts)

    if style.lower() == "plain":
        components = []
        for c in (major, minor, patch, prerelease, build):
            if c is None:
                continue
            components.append(str(c))
        return ".".join(components)

    # If style is unknown, fall back to semver
    return render(pieces, "semver")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Validate that pieces is iterable and not None
    if pieces is None:
        raise TypeError("pieces must not be None")
    try:
        has_plus = '+' in pieces
    except Exception as exc:
        raise TypeError("pieces must be an iterable that supports the 'in' operator") from exc
    return '.' if has_plus else '+'

def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    # The VersioneerConfig class is expected to be available in the surrounding
    # context (e.g., imported from the versioneer package).  This function creates
    # an instance and sets the fields that are typically required by the
    # versioneer runtime.  If the class is not available, raise an ImportError
    # with a clear message so that callers can diagnose the problem.
    try:
        cfg = VersioneerConfig()
    except Exception as exc:  # catching broad Exception to handle missing class
        raise ImportError(
            "The 'VersioneerConfig' class required by get_config() "
            "was not found. Ensure that versioneer is correctly installed "
            "and that the class is importable."
        ) from exc

    # Set the standard configuration fields.  These values closely mirror
    # the defaults used by versioneer when a repository is initialized.
    # If any of these attributes do not exist on the cfg instance, they
    # will simply be ignored.
    try:
        cfg.tag_prefix = ""  # prefix that tags must start with
    except AttributeError:
        pass

    try:
        cfg.parentdir_prefix_version = ""  # prefix for parent directory name
    except AttributeError:
        pass

    try:
        # The file that contains the generated _version__ module.
        cfg.versionfile_source = "src/_version.py"
    except AttributeError:
        pass

    try:
        # The location where the _version__ module will be written during a
        # build/wheel operation.
        cfg.versionfile_build = "src/_version.py"
    except AttributeError:
        pass

    try:
        # Whether versioneer should search parent directories for a
        # tag-based version number.
        cfg.search_parent_directories = False
    except AttributeError:
        pass

    # Some older or customized uses of versioneer may require these
    # fields to exist even if they are left unset.
    try:
        cfg.verbose = False
    except AttributeError:
        pass

    try:
        cfg.parentdir_prefix_version = cfg.parentdir_prefix_version or "pkgname-"
    except AttributeError:
        pass

    return cfg

