def register_vcs_handler(vcs):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str) or not vcs:
        raise ValueError("vcs must be a non-empty string")
    def decorator(method):
        if not callable(method):
            raise TypeError("handler must be callable")
        _vcs_registry[vcs] = method
        return method
    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Ensure the root attribute exists
        if not hasattr(self, "root"):
            raise AttributeError("The object does not have a 'root' attribute.")
        root_path = getattr(self, "root")

        # Prepare digests storage if present
        digests = getattr(self, "digests", {})

        num_objects = 0
        good_objects = 0

        # Helper to safely read file and compute sha256
        def _validate_digest(filepath):
            try:
                with open(filepath, "rb") as f:
                    data = f.read()
                    # compute digest
                    if hasattr(self, "_compute_digest"):
                        # use a custom method if present
                        return self._compute_digest(data)
                    else:
                        import hashlib
                        return hashlib.sha256(data).hexdigest()
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Failed to read or digest file '{filepath}': {e}")
                return None

        # If root_path is a file, check it directly
        if hasattr(os.path, "isfile") and os.path.isfile(root_path):
            num_objects = 1
            valid = True
            if validate_objects:
                try:
                    size = os.path.getsize(root_path)
                    if size == 0:
                        valid = False
                        if show_warnings:
                            print(f"Warning: File '{root_path}' is empty.")
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Warning: Could not get size for file '{root_path}': {e}")
            if check_digests:
                stored = digests.get(os.path.basename(root_path))
                computed = _validate_digest(root_path)
                if stored is None or computed is None or stored.lower() != computed.lower():
                    valid = False
                    if show_warnings:
                        print(f"Warning: Digest mismatch or missing for file '{root_path}'.")
            if valid:
                good_objects = 1
            return num_objects, good_objects

        # If root_path is a directory, walk it
        if hasattr(os, "walk"):
            try:
                for dirpath, dirnames, filenames in os.walk(root_path):
                    for fname in filenames:
                        filepath = os.path.join(dirpath, fname)
                        num_objects += 1
                        valid = True

                        if validate_objects:
                            try:
                                size = os.path.getsize(filepath)
                                if size == 0:
                                    valid = False
                                    if show_warnings:
                                        print(f"Warning: File '{filepath}' is empty.")
                            except Exception as e:
                                valid = False
                                if show_warnings:
                                    print(f"Warning: Could not get size for file '{filepath}': {e}")

                        if check_digests:
                            stored = digests.get(os.path.relpath(filepath, root_path))
                            if stored is None:
                                # try using just basename
                                stored = digests.get(os.path.basename(filepath))
                            computed = _validate_digest(filepath)
                            if stored is None or computed is None or stored.lower() != computed.lower():
                                valid = False
                                if show_warnings:
                                    print(f"Warning: Digest mismatch or missing for file '{filepath}'.")

                        if valid:
                            good_objects += 1
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Error walking directory '{root_path}': {e}")
        else:
            # No os.walk available; attempt simple file list
            if show_warnings:
                print("Warning: os.walk is not available; unable to traverse directory hierarchy.")
            return 0, 0

        return num_objects, good_objects

def initialize(self):
    """
    Create and initialize a new OCFL storage root.

    This method ensures that the storage root directory exists and is empty before
    OCFL objects can be placed there. If the directory already exists but
    contains files or subdirectories, an exception is raised to prevent
    accidental data loss. Any I/O problems are reported as a RuntimeError.

    Note:
        The root path is expected to be stored in an attribute named ``path``
        or ``root_path`` on the instance. Adjust the attribute name if the
        surrounding class uses a different one.
    """
    try:
        # Resolve the root path from common attribute names
        root_path = getattr(self, "path", None) or getattr(self, "root_path", None)
        if root_path is None:
            raise RuntimeError("The storage root path is not set on this instance.")

        # Convert to absolute path for consistency
        root_path = os.path.abspath(root_path)

        if os.path.exists(root_path):
            # Existing path must be a directory
            if not os.path.isdir(root_path):
                raise RuntimeError(
                    f"Specified root path '{root_path}' exists but is not a directory."
                )
            # Directory must be empty
            if os.listdir(root_path):
                raise RuntimeError(
                    f"Specified root directory '{root_path}' is not empty. "
                    f"Initialize on an empty directory."
                )
        else:
            # Create the directory
            os.makedirs(root_path, exist_ok=True)

        # Store the resolved path back to the instance for later use
        if hasattr(self, "path"):
            self.path = root_path
        else:
            self.root_path = root_path

    except OSError as exc:
        raise RuntimeError(
            f"Failed to initialize OCFL storage root at '{root_path}': {exc}"
        ) from exc

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    Parameters
    ----------
    version_dirs : list[str]
        A list of version directory names assumed to be in sequence (1, 2, 3, ...).

    Returns
    -------
    dict
        A mapping from version directory to a list of tuples describing digest
        differences.  Each tuple is (content_path, current_digest, root_digest).
        Directories without an inventory or with errors will be omitted from the
        result, but the method will log appropriate messages via `self.log`.
    """
    # Use the instance's root directory if it exists; otherwise fall back to the current working directory.
    root_dir = getattr(self, 'root_dir', os.getcwd())
    inventory_file = getattr(self, 'inventory_file', 'inventory.json')
    root_inventory_path = os.path.join(root_dir, inventory_file)

    # Helper to load JSON from a given path
    def _load_json(path):
        try:
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found: {path}")
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in inventory file {path}: {e}")

    # Load the root inventory once
    try:
        root_inventory = _load_json(root_inventory_path)
    except Exception as exc:
        # If the root inventory cannot be verified, stop the validation
        error_msg = f"Root inventory validation failed: {exc}"
        if hasattr(self, 'log'):
            self.log.error(error_msg)
        else:
            raise RuntimeError(error_msg)

    differences = {}

    for version in version_dirs:
        version_path = os.path.join(root_dir, version)
        try:
            inventory_path = os.path.join(version_path, inventory_file)
            inventory = _load_json(inventory_path)
        except Exception as exc:
            # Log the error and skip this version
            if hasattr(self, 'log'):
                self.log.warning(f"Skipping version {version}: {exc}")
            else:
                # If no logger, we print to stderr as a fallback
                print(f"Skipping version {version}: {exc}", file=sys.stderr)
            continue

        # Compare each item in the inventory with the root inventory
        diffs = []
        for path_in_inventory, current_digest in inventory.items():
            root_digest = root_inventory.get(path_in_inventory)
            if root_digest is None or root_digest != current_digest:
                diffs.append((path_in_inventory, current_digest, root_digest))
        if diffs:
            differences[version] = diffs

    return differences

def deep_merge_nodes(nodes):
    '''
    Deep merge a list of (ScalarNode, Node) pairs, merging values for duplicate keys.
    '''
    if not nodes:
        return []

    merged = {}
    for key_node, value_node in nodes:
        key = getattr(key_node, 'value', None)
        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            if isinstance(existing_value_node, ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                try:
                    merged_value = _merge_mapping_nodes(existing_value_node, value_node)
                except Exception:
                    merged_value = value_node
                merged[key] = (existing_key_node, merged_value)
            else:
                # last value wins
                merged[key] = (existing_key_node, value_node)
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())


def _merge_mapping_nodes(node1, node2):
    '''
    Recursively merge two MappingNode instances. The returned node has a new
    value list but keeps the tag from node1.
    '''
    # Preserve ordering: first node1's entries, then any new entries from node2
    merged_entries = {}
    order = []

    def add_entries(node):
        for k, v in getattr(node, 'value', []):
            kval = getattr(k, 'value', None)
            if kval not in merged_entries:
                merged_entries[kval] = (k, v)
                order.append(kval)

    add_entries(node1)
    for k, v in getattr(node2, 'value', []):
        kval = getattr(k, 'value', None)
        if kval in merged_entries:
            existing_k, existing_v = merged_entries[kval]
            if isinstance(existing_v, ruamel.yaml.nodes.MappingNode) and isinstance(v, ruamel.yaml.nodes.MappingNode):
                merged_v = _merge_mapping_nodes(existing_v, v)
                merged_entries[kval] = (existing_k, merged_v)
            else:
                merged_entries[kval] = (existing_k, v)
        else:
            merged_entries[kval] = (k, v)
            order.append(kval)

    merged_value = [merged_entries[k] for k in order]
    return ruamel.yaml.nodes.MappingNode(
        getattr(node1, 'tag', 'tag:yaml.org,2002:map'),
        merged_value
    )

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation
    if parser is None:
        raise TypeError('parser must not be None')
    if not hasattr(parser, "_actions"):
        raise TypeError(f'Expected an argparse.ArgumentParser instance, got {type(parser).__name__}')
    flags = []
    for action in parser._actions:
        try:
            opt_strings = action.option_strings
        except AttributeError:
            continue
        if opt_strings:
            flags.extend(opt_strings)
    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    # Initialize parser without adding any subparsers; subparsers are expected to be defined elsewhere.
    parser = argparse.ArgumentParser(add_help=False)
    # Allow unknown arguments; they will be ignored in the namespace.
    try:
        namespace, _ = parser.parse_known_args(unparsed_arguments)
    except Exception:
        # In case of any parsing error, return an empty namespace.
        namespace = argparse.Namespace()
    return {"global": namespace}

def deep_merge_nodes(nodes):
    '''
    Merge a list of (ScalarNode, value) pairs with deep merging for mapping values.
    '''
    # Helper to check if a node is a mapping.
    def is_mapping(node):
        return hasattr(node, 'tag') and hasattr(node, 'value') and isinstance(node.value, list)

    # Recursive merge of two values.
    def merge_values(a, b):
        if is_mapping(a) and is_mapping(b):
            return merge_mapping_nodes(a, b)
        # For non-mapping values, the last wins.
        return b

    # Merge two MappingNodes (deep merge of their contents).
    def merge_mapping_nodes(a, b):
        entries_a = a.value if hasattr(a, 'value') else []
        entries_b = b.value if hasattr(b, 'value') else []

        merged_entries = {}
        order = []

        # Process entries from a first.
        for key_node, val_node in entries_a:
            key = getattr(key_node, 'value', None)
            if key is None:
                continue
            merged_entries[key] = (key_node, val_node)
            order.append(key)

        # Merge/append entries from b.
        for key_node, val_node in entries_b:
            key = getattr(key_node, 'value', None)
            if key is None:
                continue
            if key in merged_entries:
                existing_val = merged_entries[key][1]
                new_val = merge_values(existing_val, val_node)
                # Keep the original key node from a (first occurrence)
                merged_entries[key] = (merged_entries[key][0], new_val)
            else:
                merged_entries[key] = (key_node, val_node)
                order.append(key)

        # Construct the new MappingNode instance.
        # Use the constructor of the first mapping node if possible.
        try:
            MappingNodeCls = type(a) if is_mapping(a) else type(b)
            new_value = [merged_entries[k] for k in order]
            return MappingNodeCls(tag=a.tag if hasattr(a, 'tag') else b.tag, value=new_value)
        except Exception:
            # Fallback: create a simple object that mimics a MappingNode
            class DummyMapping:
                __slots__ = ('tag', 'value')
            dm = DummyMapping()
            dm.tag = a.tag if hasattr(a, 'tag') else getattr(b, 'tag', None)
            dm.value = [merged_entries[k] for k in order]
            return dm

    # Main merging loop for top-level nodes.
    merged = {}
    order = []

    for key_node, val_node in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            continue
        if key in merged:
            existing_val = merged[key][1]
            new_val = merge_values(existing_val, val_node)
            # Keep original key node from the first occurrence
            merged[key] = (merged[key][0], new_val)
        else:
            merged[key] = (key_node, val_node)
            order.append(key)

    # Reconstruct result preserving order.
    return [(merged[k][0], merged[k][1]) for k in order]

