def paging(response, max_results):
    """
    Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.

    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if response is None:
        raise ValueError("response must not be None")
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator to yield paged slices of the response list
    def _generator():
        try:
            for start in range(0, len(response), max_results):
                end = start + max_results
                yield response[start:end]
        except Exception as exc:
            # Re-raise any unexpected error with a clearer message
            raise RuntimeError(f"Error while paging response: {exc}") from exc

    return _generator()

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    if not dicts:
        return result
    try:
        for d in dicts:
            if not isinstance(d, dict):
                raise TypeError(f"Expected dict, got {type(d).__name__}")
            for key, value in d.items():
                if isinstance(value, (int, float)):
                    result[key] = result.get(key, 0) + value
                else:
                    raise TypeError(f"Dictionary values must be numeric, got {type(value).__name__} for key '{key}'")
    except Exception as e:
        raise e
    return result

