def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate `number`
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")

    # Validate `alphabet`
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols")
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError(f"alphabet element at index {idx} is not a string: {sym!r}")

    base = len(alphabet)

    # Handle negative numbers separately
    negative = number < 0
    number = abs(number)

    # Convert to base representation
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits: List[str] = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])

    # Assemble most significant digit first
    result = ''.join(reversed(digits))

    # Apply optional padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an integer or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    # Prepend sign if necessary
    if negative:
        result = '-' + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key name")

    # Helper to replace in a single dict
    def replace_in_dict(d):
        if not isinstance(d, dict):
            return
        if register_value in d:
            d[register_value] = register_number

    # Iterate over top-level items
    for key, value in flow_params.items():
        if isinstance(value, dict):
            replace_in_dict(value)
        elif isinstance(value, list):
            # If the value is a list, iterate over elements that are dicts
            for item in value:
                replace_in_dict(item)

    return flow_params

def replace_dots(value, arg):
