def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class object, got {type(cls).__name__}")
    result = set()

    def _collect(c):
        try:
            for sub in c.__subclasses__():
                if sub not in result:
                    result.add(sub)
                    _collect(sub)
        except Exception as exc:
            # If a subclass cannot be inspected, skip it
            raise RuntimeError(f"Error retrieving subclasses of {c.__name__}") from exc

    _collect(cls)
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError(f"'string' must be of type str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"'alphabet' must be a list, got {type(alphabet).__name__}")

    # Ensure alphabet contains unique string symbols
    if len(alphabet) == 0:
        raise ValueError("Alphabet must contain at least one symbol")
    if not all(isinstance(sym, str) for sym in alphabet):
        raise TypeError("All symbols in alphabet must be strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet symbols must be unique")

    base = len(alphabet)
    symbol_to_value = {sym: i for i, sym in enumerate(alphabet)}

    # Edge case: empty string returns 0
    if string == "":
        return 0

    # Special handling for base 1 (unary)
    if base == 1:
        expected_symbol = alphabet[0]
        if any(ch != expected_symbol for ch in string):
            raise ValueError(f"String contains symbols not in the unary alphabet {alphabet}")
        return len(string)

    # General case for base >= 2
    value = 0
    for ch in string:
        if ch not in symbol_to_value:
            raise ValueError(f"Symbol '{ch}' not found in alphabet {alphabet}")
        digit = symbol_to_value[ch]
        value = value * base + digit

    return value

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError(f"Expected dict, got {type(item).__name__}")
    new_dict = {}
    for k, v in item.items():
        if isinstance(k, str):
            # Escape dots and replace wildcard '*' with a regex pattern
            converted = '^' + re.sub(r'\.', r'\\.', k).replace('*', '.*') + '$'
            new_dict[converted] = v
        else:
            # Non-string keys are left unchanged
            new_dict[k] = v
    return new_dict

def unquote(name):
    """Remove quote from the given name."""
    try:
        if not isinstance(name, str):
            return name
        # Remove leading and trailing single or double quotes, if any
        return re.sub(r"^[\"']+|[\"']+$", "", name)
    except Exception:
        # In case of any unexpected error, return the original input
        return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import shlex
    import os
    # Validate input type for s
    if s is None:
        return []
    if not isinstance(s, str):
        raise TypeError(f"Input must be a string, got {type(s).__name__}")
    # Map platform values
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0
    elif isinstance(platform, str):
        if platform.lower() == '1':
            platform = 1
        elif platform.lower() in ('0', 'windows', 'cmd'):
            platform = 0
        else:
            raise ValueError(f"Unsupported platform string: {platform!r}")
    elif isinstance(platform, int):
        if platform not in (0, 1):
            raise ValueError(f"Unsupported platform int: {platform}")
    else:
        raise TypeError(f"Unsupported platform type: {type(platform).__name__}")

    # Empty string case
    if s == '':
        return []

    try:
        if platform == 1:
            # POSIX splitting
            return shlex.split(s, posix=True)
        else:
            # Windows/CMD style splitting
            return shlex.split(s, posix=False)
    except Exception as e:
        raise ValueError(f"Failed to split command line: {e}") from e

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    import os
    from pathlib import Path
    import shutil

    # Resolve paths
    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file '{archive_path}' does not exist or is not a file.")

    base_dir = Path(tmp_path)
    try:
        base_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create temporary directory '{tmp_path}': {exc}") from exc

    # Determine extraction target directory
    if filename:
        target_dir = base_dir / filename
    else:
        # Use stem (basename without extension) as directory name
        target_dir = base_dir / archive.stem

    try:
        target_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create extraction directory '{target_dir}': {exc}") from exc

    # Unpack the archive
    try:
        shutil.unpack_archive(str(archive), str(target_dir))
    except shutil.ReadError as exc:
        raise RuntimeError(f"Failed to unpack archive '{archive_path}': {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error unpacking archive '{archive_path}': {exc}") from exc

    # Return file URL (absolute path)
    return f"file://{target_dir.resolve()}"

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        if not host:
            return False
        host_str = str(host).strip()
        if host_str.lower() == 'localhost':
            return True

        # Resolve the host to addresses
        for res in socket.getaddrinfo(host_str, None):
            family, _socktype, _proto, _canonname, sockaddr = res
            addr = sockaddr[0]
            if family == socket.AF_INET:
                if addr == '127.0.0.1':
                    return True
            elif family == socket.AF_INET6:
                if addr == '::1':
                    return True
                # Handle IPv4-mapped IPv6 addresses
                if addr.startswith('::ffff:'):
                    if addr.split('::ffff:')[1] == '127.0.0.1':
                        return True
        return False
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Basic input validation
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string path")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string containing YAML")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer (octal or decimal)")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Resolve absolute path (optional, but can avoid issues with relative paths)
    config_path = os.path.abspath(config_filename)
    parent_dir = os.path.dirname(config_path)

    # Ensure containing directories exist
    if parent_dir and not os.path.exists(parent_dir):
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except OSError as e:
            raise OSError(f"Failed to create directories for {config_path}: {e}") from e

    # Abort if file exists and overwrite is False
    if os.path.exists(config_path) and not overwrite:
        raise FileExistsError(
            f"File '{config_path}' already exists and overwrite is set to False."
        )

    # Write the rendered configuration to the file
    try:
        with open(config_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        # Set the file permission mode
        os.chmod(config_path, mode)
    except OSError as e:
        raise OSError(f"Failed to write configuration to {config_path}: {e}") from e
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Ensure matcher is a sequence with at least one element
    try:
        iterator = iter(matcher)
    except TypeError:
        raise TypeError("matcher must be a sequence containing at least the variable name")
    # Extract the name
    try:
        name = next(iterator)
    except StopIteration:
        raise ValueError("matcher must contain at least the variable name")
    # Default value if specified
    default_provided = False
    default = None
    try:
        default = next(iterator)
        default_provided = True
    except StopIteration:
        pass
    # Retrieve the environment variable
    value = os.getenv(name)
    if value is None:
        if default_provided:
            return default
        else:
            raise EnvironmentError(f"Environment variable '{name}' is not defined and no default was provided")
    return value

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    return re.escape(pattern)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import sys

    # Resolve the command string
    if isinstance(commands, (list, tuple)):
        if not commands:
            raise ValueError("commands list cannot be empty")
        # Use the first command; ignore any additional commands
        command = commands[0]
        if len(commands) > 1:
            # Emit a warning if more than one command is supplied
            if verbose:
                print(f"Warning: multiple commands supplied; only the first '{command}' will be executed.", file=sys.stderr)
    elif isinstance(commands, str):
        command = commands
    else:
        raise TypeError("commands must be a string or an iterable of strings")

    # Resolve the arguments
    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    elif isinstance(args, str):
        # Split on whitespace while respecting quoted parts
        import shlex
        args_list = shlex.split(args)
    else:
        raise TypeError("args must be a string, list, tuple, or None")

    # Build the full command
    full_cmd = [command] + args_list

    if verbose:
        print(f"Executing: {' '.join(full_cmd)!r}", file=sys.stderr)

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            shell=False,
            check=False
        )
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {command!r}") from exc
    except OSError as exc:
        raise RuntimeError(f"Error executing command {command!r}: {exc}") from exc

    # Handle errors
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=full_cmd,
            output=result.stdout,
            stderr=result.stderr
        )

    # Optionally suppress stderr output
    if not hide_stderr and result.stderr:
        print(result.stderr, file=sys.stderr)

    return result.stdout

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import sys
    import logging

    parsed_configs = {}
    error_records = []

    # Normalize input to a list
    if isinstance(config_filenames, (str, bytes)):
        filenames = [config_filenames]
    else:
        try:
            filenames = list(config_filenames)
        except Exception:
            filenames = []

    # Helper to resolve environment variables in nested structures
    def _resolve_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env(item) for item in value]
        return value

    # Process overrides
    if overrides is not None and not isinstance(overrides, dict):
        # ignore invalid overrides, but log a warning
        record = logging.LogRecord(
            name='load_configurations',
            level=logging.WARNING,
            pathname='',
            lineno=0,
            msg='Overrides provided but not a dict; ignoring.',
            args=(),
            exc_info=None
        )
        error_records.append(record)
        overrides = None

    for filename in filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
        except Exception as exc:
            rec = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to open file: {exc}',
                args=(),
                exc_info=sys.exc_info()
            )
            error_records.append(rec)
            continue

        try:
            # Attempt to parse as JSON first
            try:
                cfg = json.loads(raw)
                if not isinstance(cfg, dict):
                    raise ValueError('JSON root must be an object')
            except Exception:
                # Fallback to simple key=value parsing
                cfg = {}
                for line in raw.splitlines():
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    if '=' not in line:
                        raise ValueError(f'Invalid line (no "="): {line}')
                    key, val = line.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    # Strip surrounding quotes if present
                    if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                        val = val[1:-1]
                    cfg[key] = val

            if resolve_env:
                cfg = _resolve_env(cfg)

            # Apply overrides if provided
            if overrides:
                cfg.update(overrides)

            parsed_configs[filename] = cfg
        except Exception as exc:
            rec = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error parsing configuration: {exc}',
                args=(),
                exc_info=sys.exc_info()
            )
            error_records.append(rec)
            continue

    return parsed_configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as exc:
            raise ValueError("Failed to encode string to UTF-8") from exc
    # For non-string types, return the object unchanged
    return obj

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid
    errors = []

    # 1. Interface claim check (skip if tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    Invalid(
                        f"{candidate!r} does not declare that it provides "
                        f"{iface!r}"
                    )
                )
        except Exception as exc:
            errors.append(Invalid(f"Error checking interface provision: {exc}"))

    # 2. Method existence and signature checks
    try:
        required_methods = iface.getRequiredMethods()
    except Exception:
        # Fallback: use attributes that are callable
        required_methods = []
        for name in dir(iface):
            attr = getattr(iface, name, None)
            if callable(attr):
                required_methods.append(name)

    for name in required_methods:
        if not hasattr(candidate, name):
            errors.append(
                Invalid(f"Candidate {candidate!r} does not provide required method {name!r}")
            )
            continue
        cand_method = getattr(candidate, name)
        iface_method = getattr(iface, name, None)
        # Compare signatures if both are callables
        if callable(cand_method) and callable(iface_method):
            try:
                sig_cand = inspect.signature(cand_method)
                sig_iface = inspect.signature(iface_method)
                # Simple comparison: parameter names and kinds
                params_cand = list(sig_cand.parameters.values())
                params_iface = list(sig_iface.parameters.values())
                if len(params_cand) != len(params_iface):
                    errors.append(
                        Invalid(
                            f"Signature mismatch for {name!r}: "
                            f"expected {len(params_iface)} params, "
                            f"got {len(params_cand)}"
                        )
                    )
                    continue
                for p_c, p_i in zip(params_cand, params_iface):
                    if p_c.name != p_i.name or p_c.kind != p_i.kind:
                        errors.append(
                            Invalid(
                                f"Signature mismatch for {name!r}: "
                                f"expected param {p_i.name} ({p_i.kind}), "
                                f"got {p_c.name} ({p_c.kind})"
                            )
                        )
                        break
            except Exception as exc:
                # If introspection fails, note but don't fail
                errors.append(
                    Invalid(f"Could not introspect signature for {name!r}: {exc}")
                )
        else:
            errors.append(
                Invalid(f"Attribute {name!r} of candidate {candidate!r} is not callable")
            )

    # 3. Attribute checks
    # Try to get required attributes from interface
    attr_errors = []
    try:
        # For zope.interface >=4.5
        required_attrs = getattr(iface, "getRequiredAttributes", lambda: {})()
    except Exception:
        required_attrs = {}
    if required_attrs:
        for name, desc in required_attrs.items():
            if not hasattr(candidate, name):
                attr_errors.append(
                    Invalid(f"Candidate {candidate!r} does not provide required attribute {name!r}")
                )
            else:
                # Optional: If attribute descriptor has a type check
                # but we ignore for simplicity
                pass

    errors.extend(attr_errors)

    # 4. Result handling
    if not errors:
        return True
    if len(errors) == 1:
        raise errors[0]
    # multiple errors: aggregate message
    msg = "; ".join(str(e) for e in errors)
    raise Invalid(msg)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is not __marker:
            return default
        raise
    del self[key]
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the necessary data structures exist
    try:
        data = self._data
        freq = self._freq
    except AttributeError:
        raise AttributeError(
            "Required attributes (_data, _freq) are missing from the instance."
        ) from None

    if not data:
        raise KeyError("popitem from an empty container")

    # Identify the minimum frequency value
    min_freq = None
    for v in freq.values():
        if min_freq is None or v < min_freq:
            min_freq = v
    if min_freq is None:
        raise KeyError("Frequency data is empty; cannot determine least used item.")

    # Gather all keys that have the minimum frequency
    min_keys = [k for k, v in freq.items() if v == min_freq]
    if not min_keys:
        # Inconsistent state: data exists but no matching frequency entries
        raise KeyError("No keys with matching minimum frequency found.")

    # Resolve ties by insertion order if an ordering list is present
    key_to_remove = None
    if hasattr(self, "_order"):
        order = getattr(self, "_order")
        for k in order:
            if k in min_keys:
                key_to_remove = k
                break
    if key_to_remove is None:
        # Fall back to an arbitrary choice (first in min_keys)
        key_to_remove = min_keys[0]

    # Retrieve and remove the key/value pair
    value = data.pop(key_to_remove)
    freq.pop(key_to_remove, None)
    if hasattr(self, "_order"):
        try:
            order.remove(key_to_remove)
        except ValueError:
            # In case the key is not present in order list, ignore
            pass

    return (key_to_remove, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Attempt to get the most recently used node.  In a typical LRU
    # implementation this is the head of a doubly‑linked list.
    node = getattr(self, "head", None)
    if node is None:
        # If the list is empty we raise the same exception as collections.OrderedDict
        raise KeyError("LRUCache is empty")

    # Remove the node from the linked list
    self.head = node.next
    if self.head is not None:
        self.head.prev = None
    else:
        # The list became empty; clear the tail reference if present
        if hasattr(self, "tail"):
            setattr(self, "tail", None)

    # Remove the key from the mapping if it exists
    cache = getattr(self, "cache", None)
    if isinstance(cache, dict):
        try:
            del cache[node.key]
        except KeyError:
            # If the key is not in the mapping, silently ignore
            pass

    # Return the removed key/value pair
    return (node.key, node.value)

def _create_converter(self) -> _converting._Converter:
        """
        Create the parameter style converter.

        Returns the parameter style converter (:class:`._converting._Converter`).
        """
        try:
            converter_cls = getattr(_converting, "_Converter")
        except AttributeError as exc:
            raise RuntimeError("Converter class not found in _converting module") from exc
        try:
            return converter_cls()
        except Exception as exc:
            raise RuntimeError(f"Failed to instantiate converter: {exc}") from exc

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Check for public message indicators
        if getattr(request, "is_public", False):
            return True
        if getattr(request, "public", False):
            return True
        if getattr(request, "public_message", False):
            return True

        # Check for private message indicators
        if getattr(request, "is_private", False):
            return True
        if getattr(request, "private", False):
            return True
        if getattr(request, "private_message", False):
            return True

        # Check for legacy payload indicators
        payload = getattr(request, "payload", None)
        if isinstance(payload, dict) and payload.get("legacy") is True:
            return True

    except Exception:
        # In case of any attribute access or type-related error, treat as non-Diaspora
        return False

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if not request:
            return False

        # Try to fetch a URL or path. The request might be a dict or an object
        url = None
        if isinstance(request, dict):
            url = request.get("url") or request.get("path")
        else:
            url = getattr(request, "url", None) or getattr(request, "path", None)

        if isinstance(url, str) and url:
            lower = url.lower()
            # Common Matrix API paths use '/_matrix/' and many services use the host 'matrix.org'
            if "/_matrix/" in lower or "matrix.org" in lower:
                return True

        return False
    except Exception:
        # Be conservative: if anything goes wrong, assume not a Matrix request
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is ISO 8601 UTC time without microseconds,
    e.g. '2024-04-07T12:34:56Z'.
    """
    import datetime
    from datetime import timezone

    try:
        # Handle string input
        if isinstance(dt, str):
            try:
                # Attempt ISO format parsing (Python 3.7+)
                dt_obj = datetime.datetime.fromisoformat(dt)
            except Exception:
                # Fallback to common patterns
                for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
                    try:
                        dt_obj = datetime.datetime.strptime(dt, fmt)
                        break
                    except Exception:
                        dt_obj = None
                if dt_obj is None:
                    raise ValueError(f"Unable to parse datetime string: {dt}")

        # Handle timestamp (int or float)
        elif isinstance(dt, (int, float)):
            dt_obj = datetime.datetime.fromtimestamp(dt, tz=timezone.utc)

        # Handle datetime objects
        elif isinstance(dt, datetime.datetime):
            dt_obj = dt

        else:
            raise TypeError(f"Unsupported type for format_dt: {type(dt)}")

        # Ensure timezone-aware; assume UTC if naive
        if dt_obj.tzinfo is None:
            dt_obj = dt_obj.replace(tzinfo=timezone.utc)
        # Convert to UTC
        dt_utc = dt_obj.astimezone(timezone.utc)
        # Format without microseconds
        return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

    except Exception as exc:
        raise ValueError(f"format_dt error: {exc}")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        return ''
    try:
        import re
        from html.parser import HTMLParser

        class LinkProcessor(HTMLParser):
            def __init__(self):
                super().__init__()
                self.result = []

            def handle_starttag(self, tag, attrs):
                lower_tag = tag.lower()
                attrs = list(attrs)
                if lower_tag == 'a':
                    # Convert attrs to dict for easy manipulation
                    attr_dict = dict(attrs)
                    if 'target' not in attr_dict:
                        attr_dict['target'] = '_blank'
                    if 'rel' not in attr_dict:
                        attr_dict['rel'] = 'noopener noreferrer'
                    # Reconstruct attrs list
                    attrs = list(attr_dict.items())
                parts = [f'<{tag}']
                for k, v in attrs:
                    parts.append(f' {k}="{v}"')
                # Self‑closing tags
                if tag.lower() in {
                    'area', 'base', 'br', 'col', 'embed',
                    'hr', 'img', 'input', 'link', 'meta',
                    'param', 'source', 'track', 'wbr'
                }:
                    parts.append(' />')
                else:
                    parts.append('>')
                self.result.append(''.join(parts))

            def handle_startendtag(self, tag, attrs):
                # Treat same as starttag but with a space and slash
                parts = [f'<{tag}']
                for k, v in attrs:
                    parts.append(f' {k}="{v}"')
                parts.append(' />')
                self.result.append(''.join(parts))

            def handle_endtag(self, tag):
                self.result.append(f'</{tag}>')

            def handle_data(self, data):
                url_pattern = re.compile(
                    r'\b((?:https?://|ftp://)[^\s<>"\'\\)]+)', re.I)

                def repl(match):
                    url = match.group(1)
                    return (
                        f'<a href="{url}" target="_blank" rel="noopener noreferrer">'
                        f'{url}</a>'
                    )

                self.result.append(url_pattern.sub(repl, data))

            def get_html(self):
                return ''.join(self.result)

        parser = LinkProcessor()
        parser.feed(text)
        return parser.get_html()
    except Exception:
        # In case of any unexpected error, return the original text
        return text

def test_tag(tag: str) -> bool:
    """
    Test a word whether it could be accepted as a tag.
    A valid tag must be a non-empty string that starts with a letter or underscore
    and contains only letters, digits, or underscores.
    """
    try:
        # Ensure the input is a string and not empty
        if not isinstance(tag, str) or not tag:
            return False

        # The first character must not be a digit
        if tag[0].isdigit():
            return False

        # Each character must be alphanumeric or underscore
        for ch in tag:
            if not (ch.isalnum() or ch == "_"):
                return False

        return True
    except Exception:
        # Any unexpected errors are treated as invalid
        return False

def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        # Build a shallow dictionary of children indexed by their tag name.
        return {child.tag: child for child in node}
    except Exception as exc:
        # If the provided node cannot be iterated over or some other error occurs,
        # raise a ValueError to signal invalid input while preserving the original traceback.
        raise ValueError(f"Unable to convert node to dict: {exc}") from exc

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if document_path is not None and not isinstance(document_path, str):
        raise ValueError("document_path must be a string if provided")

    # Normalize base url (strip trailing slash)
    base_url = url.rstrip("/")

    # Determine href for NodeInfo document
    if document_path:
        # Remove any leading/trailing slashes from document_path for safe concat
        path = document_path.strip("/")
        href = f"{base_url}/{path}"
    else:
        # Default well-known path
        href = f"{base_url}/.well-known/nodeinfo"

    # Construct the well-known document structure
    well_known = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

    return well_known

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Load the public key
        if isinstance(public_key, (bytes, bytearray)):
            key_bytes = public_key
        else:
            key_bytes = public_key.encode()
        pub_key = serialization.load_pem_public_key(key_bytes)

        # Normalise the data and signature to bytes
        if isinstance(doc, (bytes, bytearray)):
            data = doc
        else:
            data = doc.encode()

        if isinstance(signature, (bytes, bytearray)):
            sig = signature
        else:
            sig = signature.encode()

        # Verify the signature using RSA PKCS1v15 with SHA1 (common for XML signatures)
        pub_key.verify(
            sig,
            data,
            padding.PKCS1v15(),
            hashes.SHA1()
        )
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not document or not document.strip():
        raise ValueError("Document is empty or whitespace")

    doc = document.strip()

    # Try JSON first
    try:
        data = json.loads(doc)
        if not isinstance(data, dict):
            raise ValueError("JSON document does not contain a dictionary")
        # Ensure the required keys are present
        subject = data.get("subject", "")
        aliases = data.get("aliases", [])
        links = data.get("links", [])
        return {"subject": subject, "aliases": aliases, "links": links}
    except Exception:
        # Fallback to XRD (XML)
        try:
            root = ET.fromstring(doc)
        except Exception as e:
            raise ValueError(f"Could not parse webfinger as XML: {e}") from None

        def _local_name(tag: str) -> str:
            """Return tag without namespace."""
            return tag.split("}", 1)[-1] if "}" in tag else tag

        subject = ""
        aliases = []
        links = []

        # Find subject
        for elem in root.iter():
            if _local_name(elem.tag).lower() == "subject":
                subject = elem.text or ""
                break

        # Find aliases
        for elem in root.iter():
            if _local_name(elem.tag).lower() == "alias":
                if elem.text:
                    aliases.append(elem.text)

        # Find links
        for elem in root.iter():
            if _local_name(elem.tag).lower() == "link":
                link_dict = {
                    k: v for k, v in elem.attrib.items() if k in ("rel", "type", "href")
                }
                if link_dict:
                    links.append(link_dict)

        return {"subject": subject, "aliases": aliases, "links": links}

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve (e.g., "alice@example.com")
    :returns: dictionary representation of the webfinger document
    """
    import urllib.request
    import urllib.parse
    import urllib.error
    import json
    import xml.etree.ElementTree as ET

    # Basic validation
    if not handle or '@' not in handle:
        return {}

    # Strip any leading "acct:" prefix
    if handle.lower().startswith('acct:'):
        handle = handle[5:]

    try:
        username, domain = handle.split('@', 1)
    except Exception:
        return {}

    resource = f"acct:{handle}"
    # Encode resource to be safe for URL
    encoded_resource = urllib.parse.quote(resource, safe='')
    target_url = f"https://{domain}/.well-known/webfinger?resource={encoded_resource}"

    req = urllib.request.Request(
        target_url,
        headers={"Accept": "application/json, application/xrd+xml, */*"},
    )

    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            content_type = resp.headers.get("Content-Type", "")
            body = resp.read()
    except (urllib.error.URLError, TimeoutError, Exception):
        # Return empty dict on any network or reading error
        return {}

    # Try JSON first
    if "application/json" in content_type.lower():
        try:
            return json.loads(body.decode("utf-8"))
        except Exception:
            return {}

    # Fallback to XML parsing
    try:
        root = ET.fromstring(body)
    except Exception:
        # Malformed XML – return empty dict
        return {}

    ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
    result = {}

    # Extract subject
    subject = root.find("xrd:subject", ns)
    if subject is not None and subject.text:
        result["subject"] = subject.text

    # Extract aliases
    aliases = [a.text for a in root.findall("xrd:alias", ns) if a.text]
    if aliases:
        result["aliases"] = aliases

    # Extract properties
    properties = {}
    for prop in root.findall("xrd:property", ns):
        prop_type = prop.attrib.get("type")
        if prop_type and prop.text:
            properties[prop_type] = prop.text
    if properties:
        result["properties"] = properties

    # Extract links
    links = []
    for link in root.findall("xrd:link", ns):
        link_dict = {}
        for attr in ("rel", "type", "href", "title", "profile"):
            if attr in link.attrib:
                link_dict[attr] = link.attrib[attr]
        if link_dict:
            links.append(link_dict)
    if links:
        result["links"] = links

    return result

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Validate input
    if not host or not isinstance(host, str):
        raise ValueError('host must be a non-empty string')

    # Construct the host-meta URL
    url = f"https://{host}/.well-known/host-meta"

    # Attempt to fetch the document using requests if available
    try:
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
        data = resp.content
    except Exception:
        # Fallback to urllib if requests is unavailable or fetch fails
        try:
            urllib_mod = __import__('urllib.request', fromlist=['Request'])
            req = urllib_mod.Request(url, headers={'User-Agent': 'diaspora-client'})
            with urllib_mod.urlopen(req, timeout=10) as fp:
                data = fp.read()
        except Exception as exc:
            raise RuntimeError(f"Failed to retrieve host-meta from {url}") from exc

    # Parse the XML into an XRD instance
    try:
        return XRD.from_xml(data)
    except Exception as exc:
        raise RuntimeError("Failed to parse the host-meta document") from exc

def list_of_file_names(settings_dirs, spec_option):
    """Return a sorted list of file names found in the given directory or
    iterable of directories. An optional ``spec_option`` can be supplied to
    filter results:

    * If ``spec_option`` starts with a '.', it will be treated as a file
      extension (case-insensitive) and only files ending with that
      extension will be returned.
    * Otherwise ``spec_option`` is treated as a case‑insensitive substring
      that must be present in the file name.

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        A single directory path or an iterable of directory paths.
    spec_option : str or None
        Optional filter string.

    Returns
    -------
    List[str]
        Sorted list of matching file names (only the base name, not the
        full path).

    Notes
    -----
    Any non‑existent or non‑directory paths are silently ignored.
    """
    import os

    # Normalize the directory list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            raise TypeError("settings_dirs must be a string or an iterable of strings")

    matched_files = []

    for dir_path in dirs:
        if not isinstance(dir_path, str):
            continue
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue

                if spec_option:
                    if isinstance(spec_option, str):
                        if spec_option.startswith('.'):
                            if not entry.lower().endswith(spec_option.lower()):
                                continue
                        else:
                            if spec_option.lower() not in entry.lower():
                                continue
                    else:
                        # spec_option is not a string, skip filtering
                        pass

                matched_files.append(entry)
        except OSError:
            # Skip directories that can't be accessed
            continue

    matched_files.sort()
    return matched_files

@classmethod
    def workspace_manager(cls):
        """Gets the workspace manager."""
        try:
            # Lazy initialization of a simple workspace manager placeholder
            if not hasattr(cls, "_workspace_manager"):
                # Create a lightweight manager object
                manager = type("SimpleWorkspaceManager", (), {})()
                cls._workspace_manager = manager
            return cls._workspace_manager
        except Exception as exc:
            # Wrap any unexpected errors in a clear RuntimeError
            raise RuntimeError(f"Unable to acquire workspace manager: {exc}") from exc

@classmethod
def plugins_manager(cls):
    """Gets the plugin manager. """
    # Return already created manager if present
    if hasattr(cls, "_plugins_manager"):
        return cls._plugins_manager
    # Attempt to load a real PluginManager implementation
    mgr = None
    try:
        from plugin_manager import PluginManager  # type: ignore
        mgr = PluginManager()
    except Exception:
        # Either the module or class is not available, fallback to a simple dict
        mgr = {}
    # Cache the manager on the class for future calls
    cls._plugins_manager = mgr
    return mgr

@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Basic validation of input
        if spec_content is None:
            raise IRValidatorException("spec_content cannot be None")
        # Load spec content from string if necessary
        if isinstance(spec_content, str):
            try:
                import yaml
                spec_dict = yaml.safe_load(spec_content)
            except Exception as e:
                raise IRValidatorException(f"Failed to parse YAML content: {e}")
        elif isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            raise IRValidatorException(
                f"Unsupported spec_content type: {type(spec_content).__name__}"
            )
        # Ensure we got a dictionary after parsing
        if not isinstance(spec_dict, dict) or spec_dict is None:
            raise IRValidatorException("Spec content must resolve to a dictionary")
        # Define required fields – adjust these to match the actual spec
        required_keys = ["name", "version", "spec"]
        missing_keys = [k for k in required_keys if k not in spec_dict]
        if missing_keys:
            raise IRValidatorException(
                f"Missing required fields in spec: {', '.join(missing_keys)}"
            )
        return spec_dict

@classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        # Basic argument validation
        if not yaml_file:
            raise IRValidatorException("No YAML file path provided")

        # Import yaml lazily to keep the method self‑contained
        try:
            import yaml
        except Exception as exc:
            raise IRValidatorException(f"Failed to import YAML parser: {exc}") from exc

        # Load the file
        try:
            with open(yaml_file, "r", encoding="utf-8") as fp:
                data = yaml.safe_load(fp)
        except FileNotFoundError as exc:
            raise IRValidatorException(f"YAML file not found: {exc}") from exc
        except Exception as exc:
            raise IRValidatorException(f"Failed to load YAML file: {exc}") from exc

        if data is None:
            raise IRValidatorException("YAML file is empty or contains no valid data")

        # Determine required fields.  Sub‑classes may override or define a class
        # attribute named REQUIRED_FIELDS.
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])

        # If no requirements are defined, just return the data
        if not required_fields:
            return data

        # Ensure required fields exist
        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(
                f"Missing required field(s) in YAML file: {', '.join(missing)}"
            )

        return data

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        if not isinstance(parser_dict, dict):
            raise TypeError("parser_dict must be a dictionary")

        # The include directive is expected to be a dict under the key 'include'.
        include_key = "include"
        if include_key not in parser_dict:
            return parser_dict

        includes = parser_dict.pop(include_key)
        if not isinstance(includes, dict):
            raise ValueError(
                f"The '{include_key}' value must be a dictionary mapping group names "
                "to either nested group definitions or file paths."
            )

        # Determine base directory for relative paths
        base_dir = getattr(self, "_spec_dir", None)
        if base_dir is None:
            # Fallback to directory of the spec file if available
            base_dir = getattr(self, "_spec_file", None)
            if base_dir is not None:
                base_dir = os.path.dirname(base_dir)
            else:
                base_dir = os.getcwd()

        for group_name, source in includes.items():
            if not isinstance(group_name, str):
                raise TypeError(f"Group name must be a string, got {type(group_name).__name__}")

            if isinstance(source, dict):
                # Merge nested dictionary into existing group, if any
                existing = parser_dict.get(group_name, {})
                if not isinstance(existing, dict):
                    raise ValueError(
                        f"Cannot merge group '{group_name}': existing "
                        f"definition is not a dictionary."
                    )
                merged = {**existing, **source}
                parser_dict[group_name] = merged
            else:
                # Assume source is a file path
                if not isinstance(source, str):
                    raise TypeError(
                        f"Include source for group '{group_name}' must be a string path, "
                        f"got {type(source).__name__}"
                    )
                include_path = source if os.path.isabs(source) else os.path.join(base_dir, source)
                try:
                    with open(include_path, "r", encoding="utf-8") as f:
                        try:
                            import yaml
                        except ImportError as exc:
                            raise ImportError(
                                "PyYAML is required to load included group files."
                            ) from exc
                        included_dict = yaml.safe_load(f)
                except FileNotFoundError as exc:
                    raise FileNotFoundError(
                        f"Included file '{include_path}' for group '{group_name}' not found."
                    ) from exc
                except Exception as exc:
                    raise ValueError(
                        f"Failed to load included group '{group_name}' from '{include_path}': {exc}"
                    ) from exc

                if not isinstance(included_dict, dict):
                    raise ValueError(
                        f"Included file '{include_path}' must contain a dictionary "
                        "definition for group '{group_name}'."
                    )

                existing = parser_dict.get(group_name, {})
                if not isinstance(existing, dict):
                    raise ValueError(
                        f"Cannot merge group '{group_name}': existing definition is not a dictionary."
                    )
                parser_dict[group_name] = {**existing, **included_dict}

        return parser_dict

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources."""
        defaults = {}
        try:
            spec = getattr(self, "spec", None)
            if not isinstance(spec, dict):
                return defaults
            for name, attr in spec.items():
                if isinstance(attr, dict):
                    # consider 'default' key or nested default
                    default_val = attr.get("default")
                    if default_val is not None:
                        defaults[name] = default_val
                # If there is no default value for the argument simply ignore it
        except Exception:
            # In case of any unexpected error we simply return an empty dict
            # rather than propagating the exception to callers.
            pass
        return defaults

def get_deprecated_args(self):
        """Returning dict with options which deprecate others."""
        deprecated = getattr(self, "_deprecated_args", None)
        if isinstance(deprecated, dict):
            # Return a copy to avoid accidental mutation of the internal mapping
            return dict(deprecated)
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import warnings

    # Ensure the inputs are dictionaries (or None)
    if cli_args is not None and not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dict (or None)")
    if answer_file_args is not None and not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dict (or None)")

    cli_args = cli_args or {}
    answer_file_args = answer_file_args or {}

    # Retrieve the mapping of deprecated arguments (old_name -> new_name or None)
    deprecated_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecated_map, dict):
        # Nothing to validate if no mapping is provided
        return

    # Collect all keys from both argument sources
    all_keys = list(cli_args.keys()) + list(answer_file_args.keys())
    seen = set()

    # Emit warnings for deprecated arguments
    for key in all_keys:
        if key in seen:
            continue
        if key in deprecated_map:
            replacement = deprecated_map[key]
            if replacement:
                msg = f"Argument '{key}' is deprecated. Use '{replacement}' instead."
            else:
                msg = f"Argument '{key}' is deprecated and will be removed in a future version."
            warnings.warn(msg, DeprecationWarning)
            seen.add(key)

    # Emit warnings if both a deprecated key and its replacement are present
    for old, new in deprecated_map.items():
        if new:  # only check when there is a replacement name
            if old in cli_args and new in cli_args:
                warnings.warn(
                    f"Both deprecated argument '{old}' and its replacement '{new}' are set in the CLI."
                    f" Consider removing the deprecated '{old}'.",
                    RuntimeWarning)
            if old in answer_file_args and new in answer_file_args:
                warnings.warn(
                    f"Both deprecated argument '{old}' and its replacement '{new}' are set in the answer file."
                    f" Consider removing the deprecated '{old}'.",
                    RuntimeWarning)

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Validate input
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    cmd = command_name.strip()
    if not cmd:
        raise ValueError("command_name cannot be empty")

    # Attempt to get the main parser
    parser = getattr(self, "parser", None)
    if parser is None:
        return []

    try:
        # Locate the SubParsersAction which holds all subcommand parsers
        subparsers_action = None
        for action in getattr(parser, "_actions", []):
            # In argparse, a SubParsersAction has a 'choices' dict attribute
            if hasattr(action, "choices") and isinstance(action.choices, dict):
                subparsers_action = action
                break

        if subparsers_action is None:
            return []

        # Ensure the requested subcommand exists
        if cmd not in subparsers_action.choices:
            return []

        subparser = subparsers_action.choices[cmd]

        # Collect all option strings for the subcommand parser
        options = []
        for action in getattr(subparser, "_actions", []):
            # Skip mutually exclusive groups or positional arguments without flags
            if action.option_strings:
                options.extend(action.option_strings)

        # Return a sorted list for consistency
        return sorted(options)
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

def get_silent_args(self, args):
    """
    Return the names of arguments that are considered "silent".

    An argument is considered silent if its value is None, False, an empty string,
    or an empty collection (list, tuple, set, dict).  The argument collection
    can be a mapping, an object with a __dict__ attribute (e.g., argparse.Namespace),
    or an iterable of 2‑item tuples (e.g., produced by zip or a list of key/value
    pairs).  Invalid input types raise a TypeError.

    :param args: The received arguments; may be a mapping, a namespace-like
                 object, or an iterable of (key, value) pairs.
    :return: list of names (keys) whose values are considered silent.
    """
    if args is None:
        return []

    # Convert the input into a dictionary if possible
    if isinstance(args, dict):
        data = args
    elif hasattr(args, "__dict__"):
        try:
            data = vars(args)
        except Exception as exc:
            raise TypeError("Failed to extract arguments from the object") from exc
    elif isinstance(args, list) or isinstance(args, tuple):
        # Accept list/tuple of 2‑item sequences
        try:
            data = dict(args)
        except Exception as exc:
            raise TypeError("Argument list must contain (key, value) tuples") from exc
    else:
        raise TypeError("args must be a mapping, namespace, or sequence of (key, value) pairs")

    if not isinstance(data, dict):
        raise TypeError("Unable to interpret args as a dictionary of arguments")

    silent_names = []
    for key, value in data.items():
        if value is None or value is False:
            silent_names.append(key)
        elif isinstance(value, str) and value == "":
            silent_names.append(key)
        elif isinstance(value, (list, tuple, set, dict)) and len(value) == 0:
            silent_names.append(key)

    return silent_names

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping like dictionary
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary mapping argument names to values")
    # Determine the list of required arguments. Prefer an attribute named 'required_args',
    # but fall back to 'requires_args' if it exists, and finally to an empty list.
    required = getattr(self, "required_args", None)
    if required is None:
        required = getattr(self, "requires_args", [])
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("required_args must be a list, tuple, or set of argument names")
    # Find any missing required arguments
    missing = [arg for arg in required if arg not in args]
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ValueError(f"Missing required argument(s): {missing_str}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    if not options_spec:
        return required
    for opt in options_spec:
        # skip if option does not have a name
        opt_name = opt.get('name')
        if not opt_name:
            continue
        cond = opt.get('required_when')
        # no condition defined means not required conditionally
        if not cond:
            continue
        matched = False
        try:
            if isinstance(cond, bool):
                matched = cond
            elif callable(cond):
                # callable might accept args, command_name, options_spec
                matched = bool(cond(args, command_name, options_spec))
            elif isinstance(cond, (str, bytes)):
                # allow string-based condition, eval in safe context
                eval_ctx = {
                    'args': args,
                    'command_name': command_name,
                    'options_spec': options_spec,
                }
                matched = bool(eval(cond, {}, eval_ctx))
            else:
                # unsupported type: skip
                matched = False
        except Exception:
            # Any error evaluating condition marks it as not matched
            matched = False
        if matched:
            required.append(opt_name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    Parameters:
        args (dict): The received arguments where keys are parameter names
            and values are the corresponding values. Strings (or lists/tuples
            of strings) will be validated against the maximum length. The
            maximum length can be set on the instance via an attribute
            ``MAX_LENGTH``; if not present, a default of 255 is used.

    Raises:
        TypeError: If ``args`` is not a dictionary.
        ValueError: If any string value exceeds the allowed length. The
            exception message contains details about each offending
            argument.

    Returns:
        None
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    max_len = getattr(self, "MAX_LENGTH", 255)
    errors = {}

    for key, value in args.items():
        # Check simple string values
        if isinstance(value, str):
            if len(value) > max_len:
                errors[key] = f"Length {len(value)} exceeds maximum {max_len}"
        # Check lists or tuples of strings
        elif isinstance(value, (list, tuple)):
            for idx, item in enumerate(value):
                if isinstance(item, str) and len(item) > max_len:
                    errors.setdefault(key, []).append(
                        f"Index {idx} length {len(item)} exceeds maximum {max_len}"
                    )
        # For all other types, no length validation is performed
        else:
            continue

    if errors:
        raise ValueError(f"Length validation failed: {errors}")

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments. It can be a mapping (like a dict) or an object
                     with attributes (e.g., argparse.Namespace).
        :raises TypeError: If the provided `args` is not compatible with the expected
                           interface or if the internal `choices` configuration is malformed.
        :raises ValueError: If any argument is present in the provided `args` but its
                            value(s) are not among the allowed choices.
        """
        # Retrieve the mapping of argument names to allowed choice lists.
        choices = getattr(self, "choices", None)
        if choices is None:
            # No choices defined; nothing to validate.
            return
        if not isinstance(choices, dict):
            raise TypeError(f"Expected self.choices to be a dict, got {type(self.choices).__name__}")

        # Helper to fetch a value from the provided args object.
        def _get_value(arg_name):
            if isinstance(args, dict):
                return args.get(arg_name)
            # For argparse.Namespace or similar objects.
            if hasattr(args, "__dict__"):
                return getattr(args, arg_name, None)
            # Fallback: try to use mapping protocol
            if hasattr(args, "get"):
                return args.get(arg_name)
            raise TypeError("The provided args object is not a dict or a namespace-style object.")

        for arg_name, allowed in choices.items():
            # Skip validation if the allowed choices are not iterable or empty.
            if allowed is None or not hasattr(allowed, "__iter__"):
                continue
            # Normalize allowed values to a set for efficient membership checks.
            allowed_set = set(allowed)

            try:
                val = _get_value(arg_name)
            except Exception:
                # If we cannot fetch the value, skip validation for this arg.
                continue

            if val is None:
                # Optional argument not supplied; skip.
                continue

            # Handle iterable values (e.g., list, tuple) separately.
            if isinstance(val, (list, tuple, set)):
                invalid = [v for v in val if v not in allowed_set]
                if invalid:
                    raise ValueError(
                        f"Argument '{arg_name}': values {invalid} are not among the allowed choices {allowed}"
                    )
                continue

            # Single scalar value.
            if val not in allowed_set:
                raise ValueError(
                    f"Argument '{arg_name}': value '{val}' is not among the allowed choices {allowed}"
                )
        # All choices validated successfully. Nothing to return.

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Default return to avoid failures when args are None or malformed
    default_return = ({}, {})

    try:
        if not args:
            return default_return

        # Convert various input types to a dictionary
        if isinstance(args, dict):
            arg_dict = args
        elif isinstance(args, list):
            # list of key/value tuples
            if all(isinstance(item, tuple) and len(item) == 2 for item in args):
                arg_dict = {k: v for k, v in args}
            else:
                # list of strings like "--key=value"
                arg_dict = {}
                for item in args:
                    if not isinstance(item, str):
                        continue
                    if item.startswith("--"):
                        item = item[2:]
                    # Treat '--flag' as True
                    if "=" in item:
                        key, value = item.split("=", 1)
                        arg_dict[key] = value
                    else:
                        arg_dict[item] = True
        else:
            # Unsupported type
            return default_return

        # Known control keys that should not be written to the spec yml
        control_keys = {
            "help", "version", "debug", "verbose", "quiet", "quiet_mode", "quiet_all",
            "log", "log_file", "log_level",
            "output", "output_file", "format",
            "dry_run", "dry", "force", "force_overwrite",
            "config", "config_file",
            "inplace", "overwrite",
        }

        control_args = {}
        nested_args = {}
        for key, value in arg_dict.items():
            if key in control_keys:
                control_args[key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args

    except Exception:
        # In case of any unexpected error, return empty dicts
        return default_return

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # Validate input dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # Nothing to do if extra_vars is None or empty
        if not extra_vars:
            return vars_dict

        # Helper for JSON parsing
        try:
            from json import loads as json_loads
        except Exception:
            json_loads = None

        # Normalize extra_vars to an iterable
        if isinstance(extra_vars, dict):
            items = [extra_vars]
        else:
            try:
                iter(extra_vars)
                items = list(extra_vars)
            except TypeError:
                items = [extra_vars]

        for item in items:
            if isinstance(item, dict):
                # Directly update with dict
                vars_dict.update(item)
            elif isinstance(item, str):
                # Strip whitespace
                raw = item.strip()
                if not raw:
                    continue
                # Handle key=value pairs
                if '=' in raw:
                    key, val = raw.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    if json_loads:
                        try:
                            parsed_val = json_loads(val)
                            val = parsed_val
                        except Exception:
                            # If JSON parsing fails, keep original string
                            pass
                    vars_dict[key] = val
                else:
                    # If string has no '=' treat as boolean flag (True)
                    key = raw
                    vars_dict[key] = True
            else:
                # Unsupported types are ignored silently
                continue

        return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Imports are local to avoid adding module level imports
    import subprocess
    import json
    import os

    # Resolve the full path of the playbook relative to the workspace
    if not os.path.isabs(playbook_path):
        workspace_path = getattr(ir_workspace, "workspace_dir", "")
        playbook_path = os.path.join(workspace_path, playbook_path)

    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' does not exist")

    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose:
        try:
            v_level = int(verbose)
        except Exception:
            raise ValueError(f"Invalid verbosity level: {verbose}")
        cmd.extend(["-" + "v" * v_level])

    # Handle extra_vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_vars = json.dumps(extra_vars)
        except Exception as e:
            raise ValueError(f"Could not serialize extra_vars: {e}")
        cmd.extend(["--extra-vars", json_vars])

    # Handle ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, val in ansible_args.items():
            if key is None:
                continue
            # Ensure flag style
            if not isinstance(key, str):
                raise TypeError(f"Argument key '{key}' must be a string")
            if val is True:
                cmd.append(key)
            elif val is False or val is None:
                # do not include flag
                continue
            else:
                cmd.extend([key, str(val)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.workspace_dir if hasattr(ir_workspace, "workspace_dir") else None,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )
    except FileNotFoundError:
        raise FileNotFoundError("ansible-playbook executable not found. "
                                "Ensure Ansible is installed and in PATH.")
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}")

    # Log output
    if ir_plugin and hasattr(ir_plugin, "log"):
        ir_plugin.log(result.stdout)
        ir_plugin.log(result.stderr, level="error")

    # Raise error on non-zero exit if desired
    if result.returncode != 0:
        raise RuntimeError(f"ansible-playbook failed with return code {result.returncode}\n"
                           f"STDOUT:\n{result.stdout}\nSTDERR:\n{result.stderr}")

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict in place.

        By default all the values are strings. This method attempts to
        convert those strings into booleans, integers, or floats when
        appropriate. Lists of strings are also processed element‑wise.
        Any value that cannot be converted is left unchanged.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc.  (Ignored in this implementation)
        :param values_dict: The dictionary of arguments.  The dictionary is modified in place.
        """
        if not isinstance(values_dict, dict):
            return

        # Helper to convert a single string value
        def _convert_val(v):
            if not isinstance(v, str):
                return v
            s = v.strip()
            if s.lower() in {"true", "false"}:
                return s.lower() == "true"
            # Handle integer
            if s.isdigit() or (s.startswith('-') and s[1:].isdigit()):
                try:
                    return int(s)
                except ValueError:
                    pass
            # Handle float
            try:
                return float(s)
            except ValueError:
                pass
            return v

        for key, value in list(values_dict.items()):
            if isinstance(value, list):
                # Convert each element if it is a string
                new_list = []
                for item in value:
                    new_list.append(_convert_val(item))
                values_dict[key] = new_list
            else:
                values_dict[key] = _convert_val(value)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Resolve plugin directory path
    try:
        plugin_dir = os.path.abspath(plugin_dir)
    except Exception:
        return {}

    if not os.path.isdir(plugin_dir):
        return {}

    # Determine spec file path; try JSON first, then YAML formats
    spec_file = None
    for fname in ('plugin.json', 'plugin.yml', 'plugin.yaml'):
        fpath = os.path.join(plugin_dir, fname)
        if os.path.isfile(fpath):
            spec_file = fpath
            break

    if not spec_file:
        return {}

    # Load the spec
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                data = json.load(f)
            else:
                if yaml is None:
                    return {}
                data = yaml.safe_load(f)
    except Exception:
        return {}

    # Helper to flatten nested dicts
    def _flatten(d, parent_key=''):
        flat = {}
        if not isinstance(d, dict):
            return flat
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(data) if isinstance(data, dict) else {}

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate types
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    # Empty root is not valid
    if root == "":
        raise ValueError("Root must not be an empty string")
    # Ensure root matches as a prefix
    # If root does not end with a separator, it can still be a prefix
    # (e.g., root='C:\\foo', path='C:\\foo\\bar')
    # If root ends with a separator, it must match exactly
    if not path.startswith(root):
        # Try adding a separator to the root if it doesn't already have one
        if not root.endswith("/") and not root.endswith("\\"):
            alt_root = root + "/"
            if path.startswith(alt_root):
                root = alt_root
            else:
                alt_root = root + "\\"
                if path.startswith(alt_root):
                    root = alt_root
                else:
                    raise ValueError(f"Root '{root}' not found in path '{path}'")
        else:
            raise ValueError(f"Root '{root}' not found in path '{path}'")
    # Extract the remaining part
    remaining = path[len(root):]
    # Remove a leading separator if present
    if remaining.startswith("/") or remaining.startswith("\\"):
        remaining = remaining[1:]
    # If nothing remains after stripping, raise an error
    if remaining == "":
        raise ValueError(f"Path '{path}' is identical to root '{root}', no relative path remains")
    return remaining
